package com.choiceman;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import java.awt.Color;

@ConfigGroup("choiceman")
public interface ChoiceManConfig extends Config
{
    @ConfigItem(
            keyName = "dimLocked",
            name = "Dim locked items",
            description = "Dim items you haven't unlocked yet.",
            position = 1
    )
    default boolean dimLocked() { return true; }

    @ConfigItem(
            keyName = "dimOpacity",
            name = "Dim opacity (0-255)",
            description = "How strong the dimming should be (higher = darker).",
            position = 2
    )
    default int dimOpacity() { return 120; }

    @ConfigItem(
            keyName = "geRestrictions",
            name = "Restrict GE to unlocked & obtained",
            description = "Hide GE entries for items you haven't unlocked and obtained at least once.",
            position = 10
    )
    default boolean geRestrictions() { return true; }

    @ConfigItem(
            keyName = "showUnlocksAlwaysOpen",
            name = "Show Unlocks Always Open",
            description = "Keep the UnlocksWidget override open when switching away from the Music tab. Use the close button to exit.",
            position = 11
    )
    default boolean showUnlocksAlwaysOpen() { return true; }

    @ConfigItem(
            keyName = "deprioritizeLockedOptions",
            name = "Deprioritize Locked Menu Options",
            description = "Deprioritize locked menu options below Walk here.",
            position = 12
    )
    default boolean deprioritizeLockedOptions() { return true; }

    @ConfigItem(
            keyName = "choiceRevealMs",
            name = "Choice reveal animation (ms)",
            description = "Per-card reveal duration for the unlock choice overlay.",
            position = 20
    )
    default int choiceRevealMs() { return 350; }

    @Alpha
    @ConfigItem(
            keyName = "accentColor",
            name = "Accent color",
            description = "Accent used for overlay borders & buttons.",
            position = 21
    )
    default Color accentColor() { return new Color(255, 204, 0, 255); }

    @ConfigItem(
            keyName = "sfxVolume",
            name = "SFX volume",
            description = "Volume for Choice Man sounds (0-100%).",
            position = 22
    )
    default int sfxVolume() { return 100; }

    @ConfigSection(
            name = "Advanced",
            description = "Advanced settings. Incorrect formatting or item IDs may break progression, restrictions, or unlock behavior.",
            position = 30,
            closedByDefault = true
    )
    String advancedSection = "advancedSection";

    @ConfigItem(
            keyName = "useCustomItems",
            name = "Use custom item list",
            description = "Loads a custom item list from ~/.runelite/choiceman/custom_items.json.",
            position = 31,
            section = advancedSection
    )
    default boolean useCustomItems() { return false; }
}

package com.choiceman;

import com.choiceman.data.ChoiceManUnlocks;
import com.choiceman.data.ItemsRepository;
import com.choiceman.menus.ActionHandler;
import com.choiceman.menus.Restrictions;
import com.choiceman.ui.*;
import com.google.gson.Gson;
import com.google.inject.Provides;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Deque;
import java.util.EnumSet;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;
import java.util.stream.Collectors;

import static net.runelite.client.RuneLite.RUNELITE_DIR;

/**
 * Main plugin. Tracks level-ups, presents unlock choices, dims/blocks locked items,
 * and integrates with the Music tab.
 */
@PluginDescriptor(
        name = "Choice Man",
        description = "Every level increase grants a choice of one unlock from a set of items. Credit to QueueScape",
        tags = {"unlock", "ironman", "rules", "ge", "shops", "overlay", "runelite"}
)
@Slf4j
public class ChoiceManPlugin extends Plugin {
    private static final int GE_SEARCH_BUILD_SCRIPT = 751;
    private static final String COL_RESET = "</col>";

    private static final String CONFIG_GROUP = "choiceman";
    private static final String CUSTOM_ITEMS_DATA_KEY = "customItems.data";
    private static final String CUSTOM_ITEMS_TIMESTAMP_KEY = "customItems.timestamp";
    private static final String CUSTOM_ITEMS_DIR = "choiceman";
    private static final String CUSTOM_ITEMS_FILE = "custom_items.json";
    private static final String CUSTOM_ITEMS_README_FILE = "custom_items_README.txt";

    private static final String DEFAULT_CUSTOM_ITEMS_TEMPLATE = String.join("\n",
            "[",
            "  {",
            "    \"name\": \"Example item - Abyssal whip\",",
            "    \"ids\": [4151]",
            "  },",
            "  {",
            "    \"name\": \"Example item - Dragon scimitar\",",
            "    \"ids\": [4587]",
            "  },",
            "  {",
            "    \"name\": \"Example item with variants\",",
            "    \"ids\": [11802, 11804, 11806, 11808]",
            "  }",
            "]",
            ""
    );

    private static final String CUSTOM_ITEMS_README = String.join("\n",
            "Choice Man custom item list",
            "",
            "Edit custom_items.json to define your own item pool.",
            "",
            "Format:",
            "[",
            "  {",
            "    \"name\": \"Abyssal whip\",",
            "    \"ids\": [4151]",
            "  },",
            "  {",
            "    \"name\": \"Dragon scimitar\",",
            "    \"ids\": [4587]",
            "  }",
            "]",
            "",
            "Rules:",
            "- The file must be valid JSON.",
            "- The root value must be an array.",
            "- Each item needs a non-empty name.",
            "- Each item needs ids as a non-empty array of positive OSRS item IDs.",
            "- Use multiple IDs for variants if you want them treated as the same base item.",
            "- After editing this file, toggle 'Use custom item list' off/on in the Choice Man config.",
            "- Valid custom lists are saved to RuneLite config so they can sync across profiles/machines.",
            ""
    );

    private static final Skill[] TRACKED_SKILLS = java.util.Arrays.stream(Skill.values())
            .toArray(Skill[]::new);

    /**
     * Queue of pending presentations across callbacks.
     * Each queued choice stores the offer count it earned at that exact total level.
     */
    private final Deque<PendingChoice> pendingChoiceQueue = new ArrayDeque<>();

    private PendingChoice activeChoice = null;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private EventBus eventBus;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private MouseManager mouseManager;

    @Getter
    @Inject
    private ItemManager itemManager;

    @Inject
    private Gson gson;

    @Inject
    private ConfigManager configManager;

    @Inject
    private ChoiceManConfig config;

    @Inject
    private ChoiceManOverlay choiceManOverlay;

    @Inject
    private UnlocksTooltipOverlay unlocksTooltipOverlay;

    @Inject
    private ItemDimmerController itemDimmerController;

    @Inject
    private ActionHandler actionHandler;

    @Inject
    private Restrictions restrictions;

    @Inject
    private UnlocksWidgetController unlocksWidgetController;

    @Inject
    private ItemsRepository itemsRepo;

    @Inject
    private ChoiceManUnlocks unlocks;

    @Inject
    private UnlocksTabUI unlocksTabUI;

    @Inject
    private CombatMinimizer combatMinimizer;

    private ChoiceManPanel choiceManPanel;
    private NavigationButton navButton;
    private MouseListener overlayMouse;

    private volatile boolean featuresActive = false;
    private volatile int lastKnownTotal = -1;
    private volatile boolean baselineReady = false;
    private volatile int lastHintRemaining = Integer.MIN_VALUE;
    private volatile int lastHintThreshold = -2;
    private volatile boolean maxHintSent = false;
    private volatile boolean autoMinimizedActive = false;

    // Chat color helpers
    private static String blue(String s) {
        return "<col=0055aa>" + s + COL_RESET;
    }

    private static String red(String s) {
        return "<col=ff4040>" + s + COL_RESET;
    }

    private static String black(String s) {
        return "<col=000000>" + s + COL_RESET;
    }

    /**
     * Number of offer cards scales with total level.
     */
    private static int choiceCountForTotal(int total) {
        if (total >= 1000) return 5;
        if (total >= 500) return 4;
        if (total >= 200) return 3;
        return 2;
    }

    /**
     * Next threshold where choice-count increases.
     */
    private static int nextThreshold(int total) {
        if (total < 200) return 200;
        if (total < 500) return 500;
        if (total < 1000) return 1000;
        return -1;
    }

    private static boolean isMilestoneTotal(int total) {
        return total == 200 || total == 500 || total == 1000;
    }

    @Provides
    ChoiceManConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(ChoiceManConfig.class);
    }

    @Override
    protected void startUp() {
        ensureCustomItemsTemplateExists();
        reloadItemRepository(false);

        if (isNormalWorld()) {
            enableFeatures();
        }
    }

    @Override
    protected void shutDown() {
        if (featuresActive) {
            disableFeatures();
        }
    }

    /**
     * Enable overlays, gating, panel, and music-tab integrations for normal worlds.
     */
    private void enableFeatures() {
        if (featuresActive) return;

        reloadItemRepository(false);

        featuresActive = true;

        unlocks.init(gson, itemsRepo);
        unlocks.loadFromDisk();

        clearPendingChoices();
        choiceManOverlay.setPendingCount(0);

        lastKnownTotal = -1;
        baselineReady = false;
        lastHintRemaining = Integer.MIN_VALUE;
        lastHintThreshold = -2;
        maxHintSent = false;
        autoMinimizedActive = false;

        // Load both backgrounds: default and gold
        choiceManOverlay.setAssets(
                "/com/choiceman/ui/panel_bg.png",
                "/com/choiceman/ui/panel_bg_gold.png",
                itemManager, itemsRepo, unlocks
        );

        choiceManOverlay.setConfig(config);

        try {
            choiceManOverlay.setSfxVolumePercent(config.sfxVolume());
        } catch (Exception ex) {
            log.debug("Failed to set initial SFX volume", ex);
        }

        choiceManOverlay.setOnPick(baseName ->
        {
            unlocks.unlockBase(baseName, itemsRepo.getIdsForBase(baseName));
            unlocks.saveToDisk();

            choiceManOverlay.setOnDismiss(() ->
                    clientThread.invoke(this::startChoiceIfNeeded));

            // Live-refresh UI that depends on unlock state
            clientThread.invokeLater(() -> unlocksWidgetController.refreshIfActive());

            if (choiceManPanel != null) {
                SwingUtilities.invokeLater(() -> choiceManPanel.refresh(unlocks));
            }

            completeActiveChoice();

            int remaining = pendingChoiceCount();
            choiceManOverlay.setPendingCount(Math.max(0, remaining));

            if (remaining > 0) {
                clientThread.invoke(this::startChoiceIfNeeded);
            }
        });

        overlayManager.add(choiceManOverlay);
        overlayManager.add(unlocksTooltipOverlay);

        overlayMouse = choiceManOverlay.getMouseAdapter();
        mouseManager.registerMouseListener(overlayMouse);

        itemDimmerController.setEnabled(config.dimLocked());
        itemDimmerController.setDimOpacity(config.dimOpacity());

        eventBus.register(itemDimmerController);
        eventBus.register(combatMinimizer);

        actionHandler.startUp();
        unlocksTabUI.startUp();

        choiceManPanel = new ChoiceManPanel(itemsRepo, unlocks, itemManager);

        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/net/runelite/client/plugins/choiceman/icon.png");
        navButton = NavigationButton.builder()
                .tooltip("Choice Man")
                .icon(icon)
                .priority(5)
                .panel(choiceManPanel)
                .build();

        clientToolbar.addNavigation(navButton);

        SwingUtilities.invokeLater(() -> choiceManPanel.refresh(unlocks));
    }

    /**
     * Disable overlays, panel, and event subscriptions.
     */
    private void disableFeatures() {
        if (!featuresActive) return;

        featuresActive = false;

        try {
            clientThread.invokeLater(unlocksWidgetController::restore);
        } catch (Exception ex) {
            log.debug("Restore unlocks view failed", ex);
        }

        try {
            actionHandler.shutDown();
        } catch (Exception ex) {
            log.debug("ActionHandler shutdown failed", ex);
        }

        try {
            eventBus.unregister(itemDimmerController);
        } catch (Exception ex) {
            log.debug("Unregister dimmer failed", ex);
        }

        try {
            eventBus.unregister(combatMinimizer);
        } catch (Exception ex) {
            log.debug("CombatMinimizer shutdown failed", ex);
        }

        try {
            unlocksTabUI.shutDown();
        } catch (Exception ex) {
            log.debug("UnlocksTabUI shutdown failed", ex);
        }

        try {
            overlayManager.remove(choiceManOverlay);
            overlayManager.remove(unlocksTooltipOverlay);
        } catch (Exception ex) {
            log.debug("Overlay removal failed", ex);
        }

        if (overlayMouse != null) {
            try {
                mouseManager.unregisterMouseListener(overlayMouse);
            } catch (Exception ex) {
                log.debug("Mouse listener unregister failed", ex);
            } finally {
                overlayMouse = null;
            }
        }

        if (navButton != null) {
            try {
                clientToolbar.removeNavigation(navButton);
            } catch (Exception ex) {
                log.debug("Nav button removal failed", ex);
            } finally {
                navButton = null;
            }
        }

        choiceManPanel = null;

        clearPendingChoices();
        choiceManOverlay.setPendingCount(0);

        lastKnownTotal = -1;
        autoMinimizedActive = false;
        baselineReady = false;
    }

    /**
     * Toggle features when hopping between normal and special worlds.
     */
    @Subscribe
    public void onWorldChanged(WorldChanged event) {
        if (isNormalWorld()) enableFeatures();
        else disableFeatures();
    }

    /**
     * Reset baseline at login to avoid double-awarding on reconnect.
     */
    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (!featuresActive) return;

        if (event.getGameState() == GameState.LOGGED_IN || event.getGameState() == GameState.LOGGING_IN) {
            baselineReady = false;
        }
    }

    /**
     * Award a pending choice per net increase in total level since the last tick.
     * Queue milestone presentations when crossing 200/500/1000.
     * Also announce how many more levels until the next choice-count threshold.
     */
    @Subscribe
    public void onGameTick(GameTick tick) {
        if (!featuresActive || client.getGameState() != GameState.LOGGED_IN) return;

        if (choiceManOverlay.isActive()
                && choiceManOverlay.isMinimized()
                && autoMinimizedActive
                && !combatMinimizer.isInCombatNow()) {
            choiceManOverlay.setMinimized(false);
            autoMinimizedActive = false;
        }

        final int current = computeTotalLevel();

        if (!baselineReady) {
            lastKnownTotal = current;
            baselineReady = true;
            announceThresholdHint(current); // initial hint after login
            return;
        }

        if (current > lastKnownTotal) {
            boolean autoMinimize = combatMinimizer.isInCombatNow();

            for (int level = lastKnownTotal + 1; level <= current; level++) {
                enqueuePendingChoice(new PendingChoice(
                        choiceCountForTotal(level),
                        isMilestoneTotal(level),
                        autoMinimize
                ));
            }

            lastKnownTotal = current;

            // Update minimized pill with true queue count
            choiceManOverlay.setPendingCount(Math.max(0, pendingChoiceCount()));

            // Chat hint about the next threshold
            announceThresholdHint(current);

            startChoiceIfNeeded();
        }
    }

    /**
     * React to live config changes (dim/opacity/SFX/GE/custom items).
     */
    @Subscribe
    public void onConfigChanged(net.runelite.client.events.ConfigChanged event) {
        if (!CONFIG_GROUP.equals(event.getGroup())) return;

        if ("useCustomItems".equals(event.getKey())) {
            // Config toggle ON reads the local file immediately and syncs it if valid.
            reloadItemRepositoryAndRefresh(true);
            return;
        }

        if (!featuresActive) return;

        switch (event.getKey()) {
            case "dimLocked":
            case "dimOpacity":
                itemDimmerController.setEnabled(config.dimLocked());
                itemDimmerController.setDimOpacity(config.dimOpacity());
                break;

            case "sfxVolume":
                try {
                    choiceManOverlay.setSfxVolumePercent(config.sfxVolume());
                } catch (Exception ex) {
                    log.debug("Failed to apply SFX volume", ex);
                }
                break;

            default:
                break;
        }
    }

    /**
     * Start a presentation if we have pending choices and the overlay is idle.
     */
    private void startChoiceIfNeeded() {
        if (choiceManOverlay.isActive()) return;

        List<String> pool = itemsRepo.getAllBasesStillLocked(unlocks);
        if (pool.isEmpty()) {
            clearPendingChoices();
            choiceManOverlay.setPendingCount(0);
            return;
        }

        PendingChoice choice = pollPendingChoice();
        if (choice == null) return;

        Collections.shuffle(pool, ThreadLocalRandom.current());

        List<String> offer = pool.stream()
                .limit(Math.min(choice.offerCount, pool.size()))
                .collect(Collectors.toList());

        choiceManOverlay.setPendingCount(Math.max(0, pendingChoiceCount()));
        choiceManOverlay.presentChoicesSequential(offer, choice.milestone);

        if (choice.autoMinimize && combatMinimizer.isInCombatNow()) {
            choiceManOverlay.setMinimized(true);
            autoMinimizedActive = true;
        }
    }

    /**
     * Mark bases as obtained the first time they appear in inventory; update dependent UI.
     */
    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        if (!featuresActive) return;

        if (event.getItemContainer() != null && event.getContainerId() == InventoryID.INV) {
            for (net.runelite.api.Item item : event.getItemContainer().getItems()) {
                if (item == null) continue;

                int canon = itemManager.canonicalize(item.getId());
                String base = itemsRepo.getBaseForId(canon);

                if (base != null && unlocks.markObtainedBaseIfFirst(base)) {
                    clientThread.invokeLater(() -> unlocksWidgetController.refreshIfActive());

                    if (choiceManPanel != null) {
                        SwingUtilities.invokeLater(() -> choiceManPanel.refresh(unlocks));
                    }
                }
            }
        }
    }

    @Subscribe
    public void onCommandExecuted(CommandExecuted e) {
        if (!featuresActive) return;
        if (!"roll".equalsIgnoreCase(e.getCommand())) return;

        Integer showCount = null;
        Integer queuedCount = null;

        for (String arg : e.getArguments()) {
            try {
                int v = Integer.parseInt(arg.trim());
                if (showCount == null) {
                    showCount = v;
                } else if (queuedCount == null) {
                    queuedCount = v;
                    break;
                }
            } catch (NumberFormatException ignored) {
            }
        }

        if (showCount == null || showCount < 1 || showCount > 5) {
            addGameMessage(black("[") + blue("Choice Man") + black("] ")
                    + "Usage: ::roll " + red("N") + " unlocks " + black("[") + red("Q") + black("] ")
                    + "(N = 1-5 cards per pick, optional Q = number of picks to queue).");
            return;
        }

        int q = queuedCount == null ? 1 : Math.max(1, Math.min(50, queuedCount)); // safety cap

        // Build pool to ensure there is at least something to show
        List<String> allLocked = itemsRepo.getAllBasesStillLocked(unlocks);
        if (allLocked.isEmpty()) {
            addGameMessage(black("[") + blue("Choice Man") + black("] ") + "No locked items remain to roll.");
            return;
        }

        // Add Q manual presentations using the requested presentation size.
        for (int i = 0; i < q; i++) {
            enqueuePendingChoice(new PendingChoice(showCount, false, false));
        }

        choiceManOverlay.setPendingCount(Math.max(0, pendingChoiceCount()));

        if (!choiceManOverlay.isActive()) {
            startChoiceIfNeeded();

            addGameMessage(black("[") + blue("Choice Man") + black("] ")
                    + "Rolling " + red(String.valueOf(q)) + " pick" + (q == 1 ? "" : "s")
                    + " with " + red(String.valueOf(showCount)) + " choices each.");
        } else {
            addGameMessage(black("[") + blue("Choice Man") + black("] ")
                    + "Queued " + red(String.valueOf(q)) + " more pick" + (q == 1 ? "" : "s")
                    + " (" + red(String.valueOf(showCount)) + " choices each).");
        }
    }

    /**
     * After GE search list is built, hide entries that are locked or never obtained.
     */
    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        if (!featuresActive || !config.geRestrictions()) return;

        if (event.getScriptId() == GE_SEARCH_BUILD_SCRIPT) {
            filterGeResults();
        }
    }

    private void filterGeResults() {
        final Widget results = client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS);
        if (results == null) return;

        final Widget[] children = results.getDynamicChildren();
        if (children == null || children.length < 2 || children.length % 3 != 0) return;

        for (int i = 0; i < children.length; i += 3) {
            final Widget row = children[i];
            final Widget icon = children[i + 1];
            final Widget item = children[i + 2];

            if (item == null) continue;

            final int canon = itemManager.canonicalize(item.getItemId());
            final String base = itemsRepo.getBaseForId(canon);

            final boolean ok = base != null && unlocks.isBaseUnlocked(base) && unlocks.isBaseObtained(base);
            if (!ok) {
                if (row != null) row.setHidden(true);
                if (icon != null) icon.setOpacity(70);
                item.setOpacity(70);
            }
        }
    }

    /**
     * @return true if an item is tracked by Choice Man (present in items.json).
     */
    public boolean isInPlay(int itemId) {
        int canon = itemManager.canonicalize(itemId);
        return itemsRepo.getBaseForId(canon) != null;
    }

    /**
     * Normal worlds exclude PvP/beta/tournament/speedrunning variants.
     */
    public boolean isNormalWorld() {
        EnumSet<WorldType> worldTypes = client.getWorldType();

        return !(worldTypes.contains(WorldType.DEADMAN)
                || worldTypes.contains(WorldType.SEASONAL)
                || worldTypes.contains(WorldType.BETA_WORLD)
                || worldTypes.contains(WorldType.PVP_ARENA)
                || worldTypes.contains(WorldType.QUEST_SPEEDRUNNING)
                || worldTypes.contains(WorldType.TOURNAMENT_WORLD));
    }

    /**
     * Compute total level from real levels only.
     */
    private int computeTotalLevel() {
        int sum = 0;
        for (Skill s : TRACKED_SKILLS) sum += client.getRealSkillLevel(s);
        return sum;
    }

    private void announceThresholdHint(int currentTotal) {
        final int currentChoices = choiceCountForTotal(currentTotal);
        final int next = nextThreshold(currentTotal);

        final String prefix = black("[") + blue("Choice Man") + black("] ");

        if (next == -1) {
            if (maxHintSent) return;

            maxHintSent = true;
            addGameMessage(prefix + "You're at the max - " + red(currentChoices + " options") + " per pick.");
            return;
        }

        maxHintSent = false;

        final int remaining = Math.max(0, next - currentTotal);
        if (remaining <= 0 || remaining % 5 != 0) return;
        if (remaining == lastHintRemaining && next == lastHintThreshold) return;

        lastHintRemaining = remaining;
        lastHintThreshold = next;

        final String levelsWord = remaining == 1 ? "level" : "levels";

        addGameMessage(prefix
                + red(remaining + " " + levelsWord) + " until your picks show "
                + red((currentChoices + 1) + " options")
                + " (threshold: " + red(String.valueOf(next)) + " total).");
    }

    private synchronized void clearPendingChoices() {
        pendingChoiceQueue.clear();
        activeChoice = null;
    }

    private synchronized int pendingChoiceCount() {
        return pendingChoiceQueue.size() + (activeChoice == null ? 0 : 1);
    }

    private synchronized void enqueuePendingChoice(PendingChoice choice) {
        pendingChoiceQueue.addLast(choice);
    }

    private synchronized PendingChoice pollPendingChoice() {
        if (activeChoice != null) {
            return null;
        }

        activeChoice = pendingChoiceQueue.pollFirst();
        return activeChoice;
    }

    private synchronized void completeActiveChoice() {
        activeChoice = null;
    }

    /**
     * Always creates the local example files if missing.
     * Existing player-edited files are never overwritten.
     */
    private Path ensureCustomItemsTemplateExists() {
        Path dir = RUNELITE_DIR.toPath().resolve(CUSTOM_ITEMS_DIR);
        Path customItemsPath = dir.resolve(CUSTOM_ITEMS_FILE);
        Path readmePath = dir.resolve(CUSTOM_ITEMS_README_FILE);

        try {
            Files.createDirectories(dir);

            if (!Files.exists(customItemsPath)) {
                Files.write(customItemsPath, DEFAULT_CUSTOM_ITEMS_TEMPLATE.getBytes(StandardCharsets.UTF_8));
            }

            if (!Files.exists(readmePath)) {
                Files.write(readmePath, CUSTOM_ITEMS_README.getBytes(StandardCharsets.UTF_8));
            }
        } catch (IOException ex) {
            log.warn("Failed to create Choice Man custom item template files", ex);
        }

        return customItemsPath;
    }

    /**
     * Loads bundled items first. If custom items are enabled, attempts custom loading.
     * <p>
     * preferLocalCustomFile:
     * - true when the user toggles the config, so their edited local file is imported immediately.
     * - false on startup, so synced config data wins over the untouched starter template.
     */
    private void reloadItemRepository(boolean preferLocalCustomFile) {
        itemsRepo.loadFromResources(gson);

        if (!config.useCustomItems()) {
            return;
        }

        String json = null;

        if (preferLocalCustomFile) {
            json = readLocalCustomItemsAndSync(true);
        }

        if (json == null) {
            json = readSyncedCustomItems(preferLocalCustomFile);
        }

        if (json == null && !preferLocalCustomFile) {
            json = readLocalCustomItemsAndSync(false);
        }

        if (json != null && !itemsRepo.loadFromString(gson, json)) {
            log.warn("Failed to load custom Choice Man items; using bundled items.");
        }
    }

    private void reloadItemRepositoryAndRefresh(boolean preferLocalCustomFile) {
        reloadItemRepository(preferLocalCustomFile);

        if (!featuresActive) {
            return;
        }

        unlocks.init(gson, itemsRepo);
        unlocks.loadFromDisk();

        clientThread.invokeLater(() -> unlocksWidgetController.refreshIfActive());

        if (choiceManPanel != null) {
            SwingUtilities.invokeLater(() -> choiceManPanel.refresh(unlocks));
        }
    }

    private String readLocalCustomItemsAndSync(boolean showMessages) {
        Path path = ensureCustomItemsTemplateExists();

        String json;
        try {
            json = new String(Files.readAllBytes(path), StandardCharsets.UTF_8);
        } catch (IOException ex) {
            log.warn("Failed to read custom Choice Man items from {}", path, ex);

            if (showMessages) {
                addGameMessage(black("[") + blue("Choice Man") + black("] ")
                        + "Failed to read custom_items.json. Using bundled items.");
            }

            return null;
        }

        if (isDefaultCustomItemsTemplate(json)) {
            if (showMessages) {
                addGameMessage(black("[") + blue("Choice Man") + black("] ")
                        + "custom_items.json is still the example template. Edit it first, then toggle this setting off/on.");
            }

            return null;
        }

        ItemsRepository.ValidationResult validation = ItemsRepository.validateCustomItemsJson(gson, json);
        if (!validation.isValid()) {
            if (showMessages) {
                addValidationErrors("custom_items.json is invalid", validation.getErrors());
            }

            return null;
        }

        configManager.setConfiguration(CONFIG_GROUP, CUSTOM_ITEMS_DATA_KEY, json);
        configManager.setConfiguration(CONFIG_GROUP, CUSTOM_ITEMS_TIMESTAMP_KEY, String.valueOf(System.currentTimeMillis()));

        return json;
    }

    private String readSyncedCustomItems(boolean showMessages) {
        String json = configManager.getConfiguration(CONFIG_GROUP, CUSTOM_ITEMS_DATA_KEY);
        if (json == null || json.trim().isEmpty()) {
            if (showMessages) {
                addGameMessage(black("[") + blue("Choice Man") + black("] ")
                        + "No synced custom item list found. Using bundled items.");
            }

            return null;
        }

        ItemsRepository.ValidationResult validation = ItemsRepository.validateCustomItemsJson(gson, json);
        if (!validation.isValid()) {
            log.warn("Synced custom Choice Man item list is invalid: {}", validation.getErrors());

            if (showMessages) {
                addValidationErrors("Synced custom item list is invalid", validation.getErrors());
            }

            return null;
        }

        return json;
    }

    private boolean isDefaultCustomItemsTemplate(String json) {
        if (json == null) {
            return false;
        }

        String normalized = json.replace("\r\n", "\n").trim();
        String template = DEFAULT_CUSTOM_ITEMS_TEMPLATE.replace("\r\n", "\n").trim();

        return normalized.equals(template);
    }

    private void addValidationErrors(String heading, List<String> errors) {
        String firstErrors = errors.stream()
                .limit(3)
                .collect(Collectors.joining("; "));

        addGameMessage(black("[") + blue("Choice Man") + black("] ")
                + heading + ": " + red(firstErrors));

        if (errors.size() > 3) {
            addGameMessage(black("[") + blue("Choice Man") + black("] ")
                    + red(String.valueOf(errors.size() - 3)) + " more validation error(s). Check custom_items.json.");
        }
    }

    private void addGameMessage(String msg) {
        try {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
        } catch (Exception ex) {
            log.debug("Failed to add chat message", ex);
        }
    }

    private static final class PendingChoice {
        private final int offerCount;
        private final boolean milestone;
        private final boolean autoMinimize;

        private PendingChoice(int offerCount, boolean milestone, boolean autoMinimize) {
            this.offerCount = offerCount;
            this.milestone = milestone;
            this.autoMinimize = autoMinimize;
        }
    }
}

package com.choiceman;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Tracks recent combat based on hitsplats.
 * Other classes can query {@link #isInCombatNow()} to gate behavior.
 */
@Singleton
public final class CombatMinimizer {
    private static final int GRACE_TICKS = 7;

    private final Client client;
    private int lastCombatTick = Integer.MIN_VALUE;

    @Inject
    public CombatMinimizer(Client client) {
        this.client = client;
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied e) {
        final Player me = client.getLocalPlayer();
        if (me == null) return;

        final boolean iWasHit = (e.getActor() == me);
        final boolean iDealtIt = e.getHitsplat() != null && e.getHitsplat().isMine();
        if (iWasHit || iDealtIt) {
            lastCombatTick = client.getTickCount();
        }
    }

    /**
     * True if seen a hitsplat in the last GRACE_TICKS.
     */
    public boolean isInCombatNow() {
        if (lastCombatTick == Integer.MIN_VALUE) return false;
        return (long) client.getTickCount() - (long) lastCombatTick <= GRACE_TICKS;
    }
}

package com.choiceman.account;

import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

/**
 * Immutable event payload published when the active account context changes.
 */
@Getter
@EqualsAndHashCode
@ToString
public final class AccountChanged {
    /**
     * Client-provided stable account hash, or {@code -1} when no account is active.
     */
    private final long hash;

    /**
     * Current local player's display name, or {@code null} if unknown at the time of emission.
     */
    private final String playerName;

    /**
     * Convenience flag indicating whether an account is considered logged in.
     * True iff {@link #hash} != -1.
     */
    private final boolean loggedIn;

    public AccountChanged(long hash, String playerName) {
        this.hash = hash;
        this.playerName = playerName;
        this.loggedIn = hash != -1;
    }
}

package com.choiceman.account;

import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.AccountHashChanged;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Tracks the current account context (account hash + display name) and emits {@link AccountChanged}
 * when it becomes known or changes.
 */
@Singleton
public class AccountManager {
    private final Client client;
    private final EventBus eventBus;

    /**
     * -1 indicates "no account".
     */
    private volatile long hash = -1;

    /**
     * May be null until the player object is available.
     */
    @Getter
    private volatile String playerName;

    /**
     * Set to true after we successfully latched a non-null name for the current hash.
     */
    private volatile boolean nameSet = false;

    @Inject
    public AccountManager(Client client, EventBus eventBus) {
        this.client = client;
        this.eventBus = eventBus;
    }

    /**
     * @return true when we have a valid account hash and a resolved player name.
     */
    public boolean ready() {
        return hash != -1 && nameSet;
    }

    /**
     * Capture initial account hash on plugin startup if already logged in.
     * Name resolution is deferred to {@link #onClientTick(ClientTick)}.
     */
    public void init() {
        if (client.getGameState() == GameState.LOGGED_IN) {
            long h = client.getAccountHash();
            if (h != -1) {
                hash = h;
                nameSet = false;
            }
        }
    }

    @Subscribe
    private void onAccountHashChanged(AccountHashChanged event) {
        long newHash = client.getAccountHash();
        if (hash != newHash) {
            hash = newHash;
            nameSet = false; // player instance/name may not be ready yet
        }
    }

    /**
     * Resolves the display name once the local player is available.
     * Runs very early every frame; keep checks cheap and exit fast.
     */
    @Subscribe
    private void onClientTick(ClientTick event) {
        // Avoid work before the client is loading or when we don't need to resolve a name.
        if (client.getGameState().getState() < GameState.LOADING.getState()) return;
        if (hash == -1 || nameSet) return;

        Player p = client.getLocalPlayer();
        if (p == null) return;

        String name = p.getName();
        if (name == null) return;

        playerName = name;
        nameSet = true;
        emit();
    }

    @Subscribe
    private void onGameStateChanged(GameStateChanged event) {
        // When hitting the login screen, clear state so downstream consumers can reset.
        if (event.getGameState() == GameState.LOGIN_SCREEN && hash != -1) {
            reset();
        }
    }

    /**
     * Clear current account context and notify listeners.
     */
    public void reset() {
        hash = -1;
        playerName = null;
        nameSet = false;
        emit();
    }

    private void emit() {
        eventBus.post(new AccountChanged(hash, playerName));
    }
}

package com.choiceman.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.*;

import static net.runelite.client.RuneLite.RUNELITE_DIR;

/**
 * Persists and queries unlock/obtain state for item bases defined by {@link ItemsRepository}.
 * JSON is stored under ~/.runelite/choiceman/ as two files: unlocked and obtained.
 * Set access uses synchronized snapshots for safe iteration and persistence.
 */
@Singleton
public class ChoiceManUnlocks {
    private static final String DIR = "choiceman";
    private static final String UNLOCKED_FILE = "unlocked_items.json";
    private static final String OBTAINED_FILE = "obtained_items.json";

    private static final String CONFIG_GROUP = "choiceman";
    private static final String SYNC_UNLOCKED_KEY = "unlockedItems.data";
    private static final String SYNC_UNLOCKED_TIMESTAMP_KEY = "unlockedItems.timestamp";
    private static final String SYNC_OBTAINED_KEY = "obtainedItems.data";
    private static final String SYNC_OBTAINED_TIMESTAMP_KEY = "obtainedItems.timestamp";

    private static final Type STRING_SET = new TypeToken<Set<String>>() {
    }.getType();

    private final Set<String> unlockedBases = Collections.synchronizedSet(new LinkedHashSet<>());
    private final Set<String> obtainedBases = Collections.synchronizedSet(new LinkedHashSet<>());

    @Inject
    private ConfigManager configManager;

    private transient Gson gson;
    private transient ItemsRepository repo;

    /**
     * Wire runtime services used for JSON I/O and base validation.
     */
    public void init(Gson gson, ItemsRepository repo) {
        this.gson = gson;
        this.repo = repo;
    }

    /**
     * True if {@code base} exists in the repository.
     */
    public boolean isBaseTracked(String base) {
        return base != null && repo != null && repo.isTrackedBase(base);
    }

    /**
     * True if the base is known and has been unlocked.
     */
    public boolean isBaseUsable(String base) {
        return isBaseTracked(base) && unlockedBases.contains(base);
    }

    public boolean isBaseUnlocked(String base) {
        return unlockedBases.contains(base);
    }

    public boolean isBaseObtained(String base) {
        return obtainedBases.contains(base);
    }

    /**
     * Mark a base as unlocked and persist the change.
     * The ids parameter is kept for call-site compatibility but is not used.
     */
    @SuppressWarnings("unused")
    public void unlockBase(String base, Set<Integer> ignoredIds) {
        if (base == null) return;

        if (unlockedBases.add(base)) {
            saveToDisk();
        }
    }

    /**
     * Mark a base as obtained the first time it is seen and persist the change.
     *
     * @return true if this call recorded the first obtain for the base.
     */
    public boolean markObtainedBaseIfFirst(String base) {
        if (base == null) return false;

        if (obtainedBases.add(base)) {
            saveToDisk();
            return true;
        }

        return false;
    }

    /**
     * Snapshot list of unlocked bases.
     */
    public List<String> unlockedList() {
        synchronized (unlockedBases) {
            return new ArrayList<>(unlockedBases);
        }
    }

    /**
     * Snapshot list of obtained bases.
     */
    public List<String> obtainedList() {
        synchronized (obtainedBases) {
            return new ArrayList<>(obtainedBases);
        }
    }

    /**
     * Loads unlock/obtain sets from local files and RuneLite config sync.
     * The newer source wins. Missing files/config are tolerated.
     */
    public void loadFromDisk() {
        try {
            Path dir = RUNELITE_DIR.toPath().resolve(DIR);
            Files.createDirectories(dir);

            Path unlockedPath = dir.resolve(UNLOCKED_FILE);
            Path obtainedPath = dir.resolve(OBTAINED_FILE);

            Set<String> localUnlocked = readSetFromDisk(unlockedPath);
            Set<String> localObtained = readSetFromDisk(obtainedPath);
            long localTimestamp = Math.max(lastModified(unlockedPath), lastModified(obtainedPath));

            Set<String> syncedUnlocked = readSetFromConfig(SYNC_UNLOCKED_KEY);
            Set<String> syncedObtained = readSetFromConfig(SYNC_OBTAINED_KEY);
            long syncedTimestamp = Math.max(
                    readTimestamp(SYNC_UNLOCKED_TIMESTAMP_KEY),
                    readTimestamp(SYNC_OBTAINED_TIMESTAMP_KEY)
            );

            boolean useSynced = syncedTimestamp > localTimestamp
                    && (syncedUnlocked != null || syncedObtained != null);

            Set<String> selectedUnlocked = useSynced
                    ? emptyIfNull(syncedUnlocked)
                    : emptyIfNull(localUnlocked);

            Set<String> selectedObtained = useSynced
                    ? emptyIfNull(syncedObtained)
                    : emptyIfNull(localObtained);

            retainTracked(selectedUnlocked);
            retainTracked(selectedObtained);

            synchronized (unlockedBases) {
                unlockedBases.clear();
                unlockedBases.addAll(selectedUnlocked);
            }

            synchronized (obtainedBases) {
                obtainedBases.clear();
                obtainedBases.addAll(selectedObtained);
            }

            if (useSynced) {
                writeJson(unlockedPath, selectedUnlocked);
                writeJson(obtainedPath, selectedObtained);
            } else if (localTimestamp > 0 && syncedTimestamp < localTimestamp) {
                saveToConfig(selectedUnlocked, selectedObtained, localTimestamp);
            }
        } catch (Exception ignored) {
        }
    }

    /**
     * Persist both unlocked and obtained sets atomically using a temp file then move.
     * Also writes the same state to RuneLite config for profile/cloud sync.
     */
    public synchronized void saveToDisk() {
        try {
            Path dir = RUNELITE_DIR.toPath().resolve(DIR);
            Files.createDirectories(dir);

            Set<String> uSnap;
            Set<String> oSnap;

            synchronized (unlockedBases) {
                uSnap = new LinkedHashSet<>(unlockedBases);
            }

            synchronized (obtainedBases) {
                oSnap = new LinkedHashSet<>(obtainedBases);
            }

            retainTracked(uSnap);
            retainTracked(oSnap);

            writeJson(dir.resolve(UNLOCKED_FILE), uSnap);
            writeJson(dir.resolve(OBTAINED_FILE), oSnap);
            saveToConfig(uSnap, oSnap, System.currentTimeMillis());
        } catch (IOException ignored) {
            // Ignore persistence errors
        }
    }

    private Set<String> readSetFromDisk(Path path) {
        if (!Files.exists(path)) {
            return null;
        }

        try (Reader r = Files.newBufferedReader(path)) {
            Set<String> s = gson.fromJson(r, STRING_SET);
            return s == null ? null : new LinkedHashSet<>(s);
        } catch (Exception ignored) {
            return null;
        }
    }

    private Set<String> readSetFromConfig(String key) {
        if (configManager == null) {
            return null;
        }

        String json = configManager.getConfiguration(CONFIG_GROUP, key);
        if (json == null || json.trim().isEmpty()) {
            return null;
        }

        try {
            Set<String> s = gson.fromJson(json, STRING_SET);
            return s == null ? null : new LinkedHashSet<>(s);
        } catch (Exception ignored) {
            return null;
        }
    }

    private void saveToConfig(Set<String> unlocked, Set<String> obtained, long timestamp) {
        if (configManager == null) {
            return;
        }

        configManager.setConfiguration(CONFIG_GROUP, SYNC_UNLOCKED_KEY, gson.toJson(unlocked));
        configManager.setConfiguration(CONFIG_GROUP, SYNC_UNLOCKED_TIMESTAMP_KEY, String.valueOf(timestamp));
        configManager.setConfiguration(CONFIG_GROUP, SYNC_OBTAINED_KEY, gson.toJson(obtained));
        configManager.setConfiguration(CONFIG_GROUP, SYNC_OBTAINED_TIMESTAMP_KEY, String.valueOf(timestamp));
    }

    private long readTimestamp(String key) {
        if (configManager == null) {
            return 0L;
        }

        String raw = configManager.getConfiguration(CONFIG_GROUP, key);
        if (raw == null || raw.trim().isEmpty()) {
            return 0L;
        }

        try {
            return Long.parseLong(raw.trim());
        } catch (NumberFormatException ignored) {
            return 0L;
        }
    }

    private long lastModified(Path path) {
        try {
            return Files.exists(path) ? Files.getLastModifiedTime(path).toMillis() : 0L;
        } catch (IOException ignored) {
            return 0L;
        }
    }

    private Set<String> emptyIfNull(Set<String> set) {
        return set == null ? new LinkedHashSet<>() : new LinkedHashSet<>(set);
    }

    private void retainTracked(Set<String> set) {
        if (repo == null) {
            return;
        }

        set.retainAll(new HashSet<>(repo.getAllBases()));
    }

    private void writeJson(Path path, Object obj) throws IOException {
        Path tmp = path.resolveSibling(path.getFileName() + ".tmp");

        try (BufferedWriter w = Files.newBufferedWriter(tmp, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
            gson.toJson(obj, w);
        }

        Files.move(tmp, path, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
    }
}

package com.choiceman.data;

import com.google.gson.*;
import lombok.Getter;

import javax.inject.Singleton;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * In-memory index of item "bases" / logical items to their concrete item IDs and vice versa.
 * <p>
 * Default data is loaded from the bundled resource:
 * /com/choiceman/items.json
 * <p>
 * Custom data can also be loaded from a synced JSON string after it has been imported.
 * <p>
 * Threading:
 * - Loads replace internal maps atomically.
 * - Readers get snapshots or unmodifiable views so callers cannot mutate internal state.
 */
@Singleton
public class ItemsRepository {
    private static final String ITEMS_RESOURCE = "/com/choiceman/items.json";

    /**
     * Maps logical/base item name to all concrete OSRS item IDs that should count as that base.
     */
    private final Map<String, Set<Integer>> baseToIds = new LinkedHashMap<>();

    /**
     * Reverse lookup from concrete item ID to logical/base item name.
     */
    private final Map<Integer, String> idToBase = new HashMap<>();

    /**
     * Forgiving parser used for bundled data and generic stream loading.
     * <p>
     * Supported formats:
     * - { "name": "...", "ids": [1, 2, 3] }
     * - { "name": "...", "id": 1 }
     * - { "name": "...", "itemid": [1, 2, 3] }
     * - { "name": "...", "itemid": "1,2,3" }
     * <p>
     * This parser skips bad entries. It does not throw validation errors.
     */
    private static void parseInto(Gson gson,
                                  InputStream in,
                                  Map<String, Set<Integer>> baseToIdsOut,
                                  Map<Integer, String> idToBaseOut) {
        try (InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8)) {
            JsonArray arr = gson.fromJson(reader, JsonArray.class);
            if (arr == null) {
                return;
            }

            for (JsonElement el : arr) {
                if (!el.isJsonObject()) {
                    continue;
                }

                JsonObject obj = el.getAsJsonObject();

                String name = obj.has("name") ? obj.get("name").getAsString() : null;
                if (name == null || (name = name.trim()).isEmpty()) {
                    continue;
                }

                Set<Integer> ids = baseToIdsOut.computeIfAbsent(name, k -> new LinkedHashSet<>());
                boolean addedAny = false;

                // Preferred format: ids: [1, 2, 3]
                if (obj.has("ids") && obj.get("ids").isJsonArray()) {
                    for (JsonElement idEl : obj.get("ids").getAsJsonArray()) {
                        addedAny |= tryAddId(name, ids, idEl, idToBaseOut);
                    }
                }

                // Legacy/simple format: id: 123
                if (!addedAny && obj.has("id")) {
                    addedAny |= tryAddId(name, ids, obj.get("id"), idToBaseOut);
                }

                // Legacy supported format: itemid: array | number | "1,2,3"
                if (!addedAny && obj.has("itemid")) {
                    JsonElement ie = obj.get("itemid");
                    if (ie.isJsonArray()) {
                        for (JsonElement idEl : ie.getAsJsonArray()) {
                            addedAny |= tryAddId(name, ids, idEl, idToBaseOut);
                        }
                    } else if (ie.isJsonPrimitive()) {
                        JsonPrimitive p = ie.getAsJsonPrimitive();
                        if (p.isNumber()) {
                            addedAny |= tryAddId(name, ids, ie, idToBaseOut);
                        } else if (p.isString()) {
                            for (String part : p.getAsString().split(",")) {
                                try {
                                    int parsed = Integer.parseInt(part.trim());
                                    addedAny |= tryAddId(name, ids, new JsonPrimitive(parsed), idToBaseOut);
                                } catch (NumberFormatException ignored) {
                                }
                            }
                        }
                    }
                }

                // Do not keep empty bases.
                if (ids.isEmpty()) {
                    baseToIdsOut.remove(name);
                }
            }
        } catch (Exception ignored) {
            // Let caller decide whether to swap maps.
        }
    }

    /**
     * Adds an item ID to both indexes if it is valid.
     * Duplicate IDs assigned to the same base are fine.
     * Duplicate IDs assigned to different bases keep the first mapping.
     */
    private static boolean tryAddId(String baseName,
                                    Set<Integer> ids,
                                    JsonElement idEl,
                                    Map<Integer, String> idToBaseOut) {
        try {
            int id = idEl.getAsInt();
            if (id <= 0) {
                return false;
            }

            boolean changed = ids.add(id);

            String existing = idToBaseOut.get(id);
            if (existing == null || existing.equals(baseName)) {
                idToBaseOut.put(id, baseName);
            }

            return changed;
        } catch (Exception ignored) {
            return false;
        }
    }

    /**
     * Strictly validates player-provided custom_items.json.
     * <p>
     * This is used before saving the custom list to ConfigManager/cloud sync.
     * <p>
     * Required custom format:
     * [
     * {
     * "name": "Abyssal whip",
     * "ids": [4151]
     * }
     * ]
     * <p>
     * For convenience, "id" and "itemid" are still accepted, but "ids" is preferred.
     */
    public static ValidationResult validateCustomItemsJson(Gson gson, String json) {
        Map<String, Set<Integer>> parsedBaseToIds = new LinkedHashMap<>();
        Map<Integer, String> parsedIdToBase = new HashMap<>();
        List<String> errors = new ArrayList<>();

        if (json == null || json.trim().isEmpty()) {
            errors.add("File is empty.");
            return new ValidationResult(false, errors, parsedBaseToIds, parsedIdToBase);
        }

        JsonElement root;
        try {
            root = gson.fromJson(new StringReader(json), JsonElement.class);
        } catch (Exception e) {
            errors.add("File is not valid JSON: " + e.getMessage());
            return new ValidationResult(false, errors, parsedBaseToIds, parsedIdToBase);
        }

        if (root == null || !root.isJsonArray()) {
            errors.add("Root value must be a JSON array.");
            return new ValidationResult(false, errors, parsedBaseToIds, parsedIdToBase);
        }

        JsonArray arr = root.getAsJsonArray();
        if (arr.size() == 0) {
            errors.add("Item list is empty.");
            return new ValidationResult(false, errors, parsedBaseToIds, parsedIdToBase);
        }

        for (int i = 0; i < arr.size(); i++) {
            JsonElement el = arr.get(i);
            String prefix = "Entry " + (i + 1) + ": ";

            if (!el.isJsonObject()) {
                errors.add(prefix + "must be an object.");
                continue;
            }

            JsonObject obj = el.getAsJsonObject();

            String name = null;
            if (obj.has("name") && obj.get("name").isJsonPrimitive()) {
                name = obj.get("name").getAsString();
            }

            if (name == null || (name = name.trim()).isEmpty()) {
                errors.add(prefix + "missing non-empty name.");
                continue;
            }

            List<Integer> ids = collectIdsForValidation(obj, prefix, errors);
            if (ids.isEmpty()) {
                errors.add(prefix + "\"" + name + "\" has no valid positive item IDs.");
                continue;
            }

            Set<Integer> set = parsedBaseToIds.computeIfAbsent(name, k -> new LinkedHashSet<>());
            for (int id : ids) {
                String existingBase = parsedIdToBase.get(id);
                if (existingBase != null && !existingBase.equals(name)) {
                    errors.add(prefix + "item ID " + id + " is already assigned to \"" + existingBase + "\".");
                    continue;
                }

                set.add(id);
                parsedIdToBase.put(id, name);
            }
        }

        parsedBaseToIds.entrySet().removeIf(e -> e.getValue().isEmpty());

        if (parsedBaseToIds.isEmpty()) {
            errors.add("No valid items were found.");
        }

        return new ValidationResult(errors.isEmpty(), errors, parsedBaseToIds, parsedIdToBase);
    }

    /**
     * Collects item IDs from supported fields for validation.
     * <p>
     * Preferred:
     * - ids: [1, 2, 3]
     * <p>
     * Accepted for compatibility:
     * - id: 1
     * - itemid: [1, 2, 3]
     * - itemid: "1,2,3"
     */
    private static List<Integer> collectIdsForValidation(JsonObject obj, String prefix, List<String> errors) {
        List<Integer> ids = new ArrayList<>();

        if (obj.has("ids")) {
            JsonElement idsEl = obj.get("ids");
            if (!idsEl.isJsonArray()) {
                errors.add(prefix + "\"ids\" must be an array.");
                return ids;
            }

            for (JsonElement idEl : idsEl.getAsJsonArray()) {
                addValidatedId(idEl, ids, prefix, errors);
            }

            return ids;
        }

        if (obj.has("id")) {
            addValidatedId(obj.get("id"), ids, prefix, errors);
            return ids;
        }

        if (obj.has("itemid")) {
            JsonElement itemIdEl = obj.get("itemid");

            if (itemIdEl.isJsonArray()) {
                for (JsonElement idEl : itemIdEl.getAsJsonArray()) {
                    addValidatedId(idEl, ids, prefix, errors);
                }
            } else if (itemIdEl.isJsonPrimitive() && itemIdEl.getAsJsonPrimitive().isString()) {
                for (String part : itemIdEl.getAsString().split(",")) {
                    try {
                        int id = Integer.parseInt(part.trim());
                        if (id > 0) {
                            ids.add(id);
                        } else {
                            errors.add(prefix + "item ID must be positive: " + part.trim());
                        }
                    } catch (NumberFormatException e) {
                        errors.add(prefix + "invalid item ID: " + part.trim());
                    }
                }
            } else {
                addValidatedId(itemIdEl, ids, prefix, errors);
            }

            return ids;
        }

        errors.add(prefix + "missing \"ids\" array.");
        return ids;
    }

    /**
     * Adds one validated positive item ID, or records a validation error.
     */
    private static void addValidatedId(JsonElement idEl, List<Integer> ids, String prefix, List<String> errors) {
        try {
            int id = idEl.getAsInt();
            if (id <= 0) {
                errors.add(prefix + "item ID must be positive: " + id);
                return;
            }

            ids.add(id);
        } catch (Exception e) {
            errors.add(prefix + "invalid item ID: " + idEl);
        }
    }

    /**
     * Load from the default bundled resource.
     * If the resource is missing or invalid, the repository is cleared.
     */
    public void loadFromResources(Gson gson) {
        Map<String, Set<Integer>> newBaseToIds = new LinkedHashMap<>();
        Map<Integer, String> newIdToBase = new HashMap<>();

        try (InputStream in = ItemsRepository.class.getResourceAsStream(ITEMS_RESOURCE)) {
            if (in != null) {
                parseInto(gson, in, newBaseToIds, newIdToBase);
            }
        } catch (Exception ignored) {
            // Fall through to swap cleared maps.
        }

        synchronized (this) {
            baseToIds.clear();
            idToBase.clear();
            baseToIds.putAll(newBaseToIds);
            idToBase.putAll(newIdToBase);
        }
    }

    /**
     * Load from an arbitrary input stream.
     * <p>
     * On error, current data remains unchanged.
     */
    public void loadFromStream(Gson gson, InputStream in) {
        if (in == null) {
            return;
        }

        Map<String, Set<Integer>> newBaseToIds = new LinkedHashMap<>();
        Map<Integer, String> newIdToBase = new HashMap<>();

        try {
            parseInto(gson, in, newBaseToIds, newIdToBase);
        } catch (Exception ignored) {
            return;
        }

        if (newBaseToIds.isEmpty()) {
            return;
        }

        synchronized (this) {
            baseToIds.clear();
            idToBase.clear();
            baseToIds.putAll(newBaseToIds);
            idToBase.putAll(newIdToBase);
        }
    }

    /**
     * Strictly load a custom JSON string.
     * This is used for the cloud-synced custom item list stored in ConfigManager.
     *
     * @return true if the repository was replaced with the custom list.
     */
    public boolean loadFromString(Gson gson, String json) {
        ValidationResult result = validateCustomItemsJson(gson, json);
        if (!result.isValid()) {
            return false;
        }

        synchronized (this) {
            baseToIds.clear();
            idToBase.clear();
            baseToIds.putAll(result.parsedBaseToIds);
            idToBase.putAll(result.parsedIdToBase);
        }

        return true;
    }

    /**
     * Returns the base name for a concrete item ID, or null if unknown.
     */
    public String getBaseForId(int id) {
        synchronized (this) {
            return idToBase.get(id);
        }
    }

    /**
     * Returns an immutable snapshot of item IDs for the given base.
     * <p>
     * Empty set if the base is unknown.
     */
    public Set<Integer> getIdsForBase(String base) {
        synchronized (this) {
            Set<Integer> ids = baseToIds.get(base);
            return ids == null
                    ? Collections.emptySet()
                    : Collections.unmodifiableSet(new LinkedHashSet<>(ids));
        }
    }

    /**
     * Returns an immutable snapshot of all known base names.
     */
    public List<String> getAllBases() {
        synchronized (this) {
            return new ArrayList<>(baseToIds.keySet());
        }
    }

    /**
     * Returns base names that are present in the repo but still locked per the provided unlock state.
     */
    public List<String> getAllBasesStillLocked(ChoiceManUnlocks unlocks) {
        List<String> out = new ArrayList<>();

        synchronized (this) {
            for (String b : baseToIds.keySet()) {
                if (!unlocks.isBaseUnlocked(b)) {
                    out.add(b);
                }
            }
        }

        return out;
    }

    /**
     * True if the base name exists in the repository.
     */
    public boolean isTrackedBase(String base) {
        synchronized (this) {
            return baseToIds.containsKey(base);
        }
    }

    /**
     * Result object used when validating player provided custom_items.json.
     * Validation is intentionally stricter than the bundled parser so players get
     * helpful feedback instead of silently importing a broken list.
     */
    public static final class ValidationResult {
        @Getter
        private final boolean valid;

        @Getter
        private final List<String> errors;

        private final Map<String, Set<Integer>> parsedBaseToIds;
        private final Map<Integer, String> parsedIdToBase;

        private ValidationResult(
                boolean valid,
                List<String> errors,
                Map<String, Set<Integer>> parsedBaseToIds,
                Map<Integer, String> parsedIdToBase) {
            this.valid = valid;
            this.errors = Collections.unmodifiableList(new ArrayList<>(errors));
            this.parsedBaseToIds = parsedBaseToIds;
            this.parsedIdToBase = parsedIdToBase;
        }
    }
}

package com.choiceman.filters;

import lombok.Getter;
import net.runelite.api.gameval.ItemID;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Maps ensouled head item IDs (including untradeable drop IDs) to their tradeable IDs.
 * Non-ensouled or unknown IDs are returned unchanged by {@link #toTradeableId(int)}.
 */
public final class EnsouledHeadMapping {

    @Getter
    public static final Map<Integer, Integer> ENSOULED_CANONICAL_ID;

    static {
        Map<Integer, Integer> idMap = new HashMap<>();

        java.util.function.BiConsumer<Integer, Integer> pair = (untradeable, tradeable) -> {
            idMap.put(untradeable, tradeable);
            idMap.put(tradeable, tradeable);
        };

        pair.accept(ItemID.ARCEUUS_CORPSE_GOBLIN_INITIAL, ItemID.ARCEUUS_CORPSE_GOBLIN); // Goblin
        pair.accept(ItemID.ARCEUUS_CORPSE_MONKEY_INITIAL, ItemID.ARCEUUS_CORPSE_MONKEY); // Monkey
        pair.accept(ItemID.ARCEUUS_CORPSE_IMP_INITIAL, ItemID.ARCEUUS_CORPSE_IMP); // Imp
        pair.accept(ItemID.ARCEUUS_CORPSE_MINOTAUR_INITIAL, ItemID.ARCEUUS_CORPSE_MINOTAUR); // Minotaur
        pair.accept(ItemID.ARCEUUS_CORPSE_SCORPION_INITIAL, ItemID.ARCEUUS_CORPSE_SCORPION); // Scorpion
        pair.accept(ItemID.ARCEUUS_CORPSE_BEAR_INITIAL, ItemID.ARCEUUS_CORPSE_BEAR); // Bear
        pair.accept(ItemID.ARCEUUS_CORPSE_UNICORN_INITIAL, ItemID.ARCEUUS_CORPSE_UNICORN); // Unicorn
        pair.accept(ItemID.ARCEUUS_CORPSE_DOG_INITIAL, ItemID.ARCEUUS_CORPSE_DOG); // Dog
        pair.accept(ItemID.ARCEUUS_CORPSE_CHAOSDRUID_INITIAL, ItemID.ARCEUUS_CORPSE_CHAOSDRUID); // Chaos Druid
        pair.accept(ItemID.ARCEUUS_CORPSE_GIANT_INITIAL, ItemID.ARCEUUS_CORPSE_GIANT); // Giant
        pair.accept(ItemID.ARCEUUS_CORPSE_OGRE_INITIAL, ItemID.ARCEUUS_CORPSE_OGRE); // Ogre
        pair.accept(ItemID.ARCEUUS_CORPSE_ELF_INITIAL, ItemID.ARCEUUS_CORPSE_ELF); // Elf
        pair.accept(ItemID.ARCEUUS_CORPSE_TROLL_INITIAL, ItemID.ARCEUUS_CORPSE_TROLL); // Troll
        pair.accept(ItemID.ARCEUUS_CORPSE_HORROR_INITIAL, ItemID.ARCEUUS_CORPSE_HORROR); // Horror
        pair.accept(ItemID.ARCEUUS_CORPSE_KALPHITE_INITIAL, ItemID.ARCEUUS_CORPSE_KALPHITE); // Kalphite
        pair.accept(ItemID.ARCEUUS_CORPSE_DAGANNOTH_INITIAL, ItemID.ARCEUUS_CORPSE_DAGANNOTH); // Dagannoth
        pair.accept(ItemID.ARCEUUS_CORPSE_BLOODVELD_INITIAL, ItemID.ARCEUUS_CORPSE_BLOODVELD); // Bloodveld
        pair.accept(ItemID.ARCEUUS_CORPSE_TZHAAR_INITIAL, ItemID.ARCEUUS_CORPSE_TZHAAR); // TzHaar
        pair.accept(ItemID.ARCEUUS_CORPSE_DEMON_INITIAL, ItemID.ARCEUUS_CORPSE_DEMON); // Demon
        pair.accept(ItemID.ARCEUUS_CORPSE_AVIANSIE_INITIAL, ItemID.ARCEUUS_CORPSE_AVIANSIE); // Aviansie
        pair.accept(ItemID.ARCEUUS_CORPSE_ABYSSAL_INITIAL, ItemID.ARCEUUS_CORPSE_ABYSSAL); // Abyssal
        pair.accept(ItemID.ARCEUUS_CORPSE_DRAGON_INITIAL, ItemID.ARCEUUS_CORPSE_DRAGON); // Dragon
        pair.accept(ItemID.ARCEUUS_CORPSE_HELLHOUND_INITIAL, ItemID.ARCEUUS_CORPSE_HELLHOUND); // Hellhound

        ENSOULED_CANONICAL_ID = Collections.unmodifiableMap(idMap);
    }

    private EnsouledHeadMapping() {
    }

    /**
     * Returns the tradeable ID for any ensouled head item ID.
     * If the ID is already tradeable or not recognized as an ensouled head, it's returned unchanged.
     */
    public static int toTradeableId(int itemId) {
        return ENSOULED_CANONICAL_ID.getOrDefault(itemId, itemId);
    }
}

package com.choiceman.menus;

import com.choiceman.ChoiceManConfig;
import com.choiceman.ChoiceManPlugin;
import com.choiceman.data.ChoiceManUnlocks;
import com.choiceman.data.ItemsRepository;
import com.choiceman.filters.EnsouledHeadMapping;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;

/**
 * Central gatekeeper for Choice Man menu interactions.
 */
@Singleton
public class ActionHandler
{
    private static final Set<MenuAction> DISABLED_ACTIONS = EnumSet.of(
            MenuAction.CC_OP,
            MenuAction.WIDGET_TARGET,
            MenuAction.WIDGET_TARGET_ON_WIDGET
    );

    private static final Set<MenuAction> GROUND_ACTIONS = EnumSet.of(
            MenuAction.GROUND_ITEM_FIRST_OPTION,
            MenuAction.GROUND_ITEM_SECOND_OPTION,
            MenuAction.GROUND_ITEM_THIRD_OPTION,
            MenuAction.GROUND_ITEM_FOURTH_OPTION,
            MenuAction.GROUND_ITEM_FIFTH_OPTION
    );

    private static final Set<Integer> ALWAYS_ALLOW_OBJECT_IDS = new HashSet<>();

    private static final EnumSet<MenuAction> GAME_OBJECT_ACTIONS = EnumSet.of(
            MenuAction.GAME_OBJECT_FIRST_OPTION,
            MenuAction.GAME_OBJECT_SECOND_OPTION,
            MenuAction.GAME_OBJECT_THIRD_OPTION,
            MenuAction.GAME_OBJECT_FOURTH_OPTION,
            MenuAction.GAME_OBJECT_FIFTH_OPTION
    );

    private static final Set<Integer> ENABLED_UI_GROUPS = new HashSet<>();

    private static final int ORBS_GROUP = InterfaceID.Orbs.UNIVERSE >>> 16;

    static
    {
        ALWAYS_ALLOW_OBJECT_IDS.add(net.runelite.api.gameval.ObjectID.CATABOW);

        for (EnabledUI ui : EnabledUI.values())
        {
            ENABLED_UI_GROUPS.add(ui.getId());
        }
    }

    private static final Consumer<MenuEntry> DISABLED = e -> { };

    @Inject private Client client;
    @Inject private EventBus eventBus;
    @Inject private ChoiceManPlugin plugin;
    @Inject private ChoiceManConfig config;
    @Inject private Restrictions restrictions;
    @Inject private ChoiceManUnlocks unlocks;
    @Inject private ItemsRepository itemsRepo;
    @Inject private ItemManager itemManager;

    @Getter
    @Setter
    private int enabledUIOpen = -1;

    public void startUp()
    {
        eventBus.register(this);
        eventBus.register(restrictions);
    }

    public void shutDown()
    {
        eventBus.unregister(this);
        eventBus.unregister(restrictions);
        enabledUIOpen = -1;
    }

    private EnabledUI currentEnabledUi()
    {
        return enabledUIOpen == -1 ? null : EnabledUI.fromGroupId(enabledUIOpen);
    }

    private boolean inactive()
    {
        return client.getGameState().getState() < GameState.LOADING.getState();
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        if (event.getGroupId() == enabledUIOpen)
        {
            enabledUIOpen = -1;
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (ENABLED_UI_GROUPS.contains(event.getGroupId()))
        {
            enabledUIOpen = event.getGroupId();
        }
    }

    /**
     * Normalize a MenuEntryAdded into a canonical item id, or -1 when the row is not item-based.
     */
    private int getItemId(MenuEntryAdded event, MenuEntry entry)
    {
        MenuAction type = entry.getType();
        boolean hasItemId = entry.getItemId() > 0 || event.getItemId() > 0;
        if (!GROUND_ACTIONS.contains(type) && !hasItemId)
        {
            return -1;
        }

        int raw = GROUND_ACTIONS.contains(type)
                ? event.getIdentifier()
                : Math.max(event.getItemId(), entry.getItemId());

        int mapped = EnsouledHeadMapping.toTradeableId(raw);
        return itemManager.canonicalize(mapped);
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (inactive())
        {
            return;
        }

        EnabledUI ui = currentEnabledUi();
        if (ui != null && !ui.isGreyLockedItems())
        {
            return;
        }

        MenuEntry entry = event.getMenuEntry();
        MenuAction action = entry.getType();
        int id = getItemId(event, entry);

        boolean allow = isGroundItem(entry)
                ? !isLockedGroundItem(id)
                : isEnabled(id, entry, action);

        if (!allow)
        {
            String option = Text.removeTags(entry.getOption());
            String target = Text.removeTags(entry.getTarget());

            entry.setOption("<col=808080>" + option);
            entry.setTarget("<col=808080>" + target);
            entry.onClick(DISABLED);

            if (config.deprioritizeLockedOptions())
            {
                entry.setDeprioritized(true);
            }
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (event.getMenuEntry().onClick() == DISABLED)
        {
            event.consume();
            return;
        }

        handleGroundItems(itemManager, unlocks, itemsRepo, event, plugin);
    }

    private static boolean isGroundItem(MenuEntry entry)
    {
        return GROUND_ACTIONS.contains(entry.getType());
    }

    /**
     * Ground-item safeguard used by the click handler.
     */
    public static void handleGroundItems(
            ItemManager itemManager,
            ChoiceManUnlocks unlocks,
            ItemsRepository itemsRepo,
            MenuOptionClicked event,
            ChoiceManPlugin plugin)
    {
        MenuAction action = event.getMenuAction();
        if (action != null && GROUND_ACTIONS.contains(action))
        {
            int rawItemId = event.getId() != -1
                    ? event.getId()
                    : event.getMenuEntry().getItemId();

            int mapped = EnsouledHeadMapping.toTradeableId(rawItemId);
            int canonicalGroundId = itemManager.canonicalize(mapped);
            String base = itemsRepo.getBaseForId(canonicalGroundId);

            if (base != null && !unlocks.isBaseUsable(base))
            {
                event.consume();
            }
        }
    }

    private boolean isLockedGroundItem(int canonicalId)
    {
        if (canonicalId <= 0)
        {
            return false;
        }

        String base = itemsRepo.getBaseForId(canonicalId);
        return base != null && !unlocks.isBaseUsable(base);
    }

    private boolean isHealthOrbCure(MenuEntry entry)
    {
        if (entry.getType() != MenuAction.CC_OP)
        {
            return false;
        }

        if (!"cure".equalsIgnoreCase(Text.removeTags(entry.getOption())))
        {
            return false;
        }

        int w1 = entry.getParam1();
        int w0 = entry.getParam0();
        return (w1 >>> 16) == ORBS_GROUP || (w0 >>> 16) == ORBS_GROUP;
    }

    private boolean isFurnaceSmelt(MenuEntry entry)
    {
        if (!GAME_OBJECT_ACTIONS.contains(entry.getType()))
        {
            return false;
        }

        String option = Text.removeTags(entry.getOption());
        String target = Text.removeTags(entry.getTarget());

        return "smelt".equalsIgnoreCase(option)
                && target != null
                && target.toLowerCase().contains("furnace");
    }

    /**
     * Core gating for non-ground rows.
     */
    private boolean isEnabled(int id, MenuEntry entry, MenuAction action)
    {
        if (isHealthOrbCure(entry) || isFurnaceSmelt(entry))
        {
            return true;
        }

        String option = Text.removeTags(entry.getOption());
        String target = Text.removeTags(entry.getTarget());

        EnabledUI ui = currentEnabledUi();
        if (ui != null && ui.isAllowAllActions())
        {
            return true;
        }

        if (GAME_OBJECT_ACTIONS.contains(action)
                && ALWAYS_ALLOW_OBJECT_IDS.contains(entry.getIdentifier()))
        {
            return true;
        }

        if (option.equalsIgnoreCase("drop") || option.equalsIgnoreCase("check"))
        {
            return true;
        }

        if (option.equalsIgnoreCase("clean") || option.equalsIgnoreCase("rub"))
        {
            if (!plugin.isInPlay(id))
            {
                return true;
            }

            return isItemUsable(id);
        }

        // Barehand barbarian fishing / Tempoross spirit pool exception.
        if ("harpoon".equalsIgnoreCase(option) && !hasAnyHarpoonInInvOrWorn())
        {
            String normalizedTarget = target.toLowerCase();
            if (normalizedTarget.contains("fishing spot") || normalizedTarget.contains("spirit pool"))
            {
                return true;
            }
        }

        if (SkillOp.isSkillOp(option))
        {
            return restrictions.isSkillOpEnabled(option);
        }

        if (Spell.isSpell(option))
        {
            return restrictions.isSpellOpEnabled(option);
        }

        if (Spell.isSpell(target))
        {
            return restrictions.isSpellOpEnabled(target);
        }

        boolean enabled = !DISABLED_ACTIONS.contains(action);
        if (enabled)
        {
            return true;
        }

        if (id == 0 || id == -1 || !plugin.isInPlay(id))
        {
            return true;
        }

        return isItemUsable(id);
    }

    private boolean isItemUsable(int itemId)
    {
        String base = itemsRepo.getBaseForId(itemId);
        return base != null && unlocks.isBaseUsable(base);
    }

    private boolean hasAnyHarpoonInInvOrWorn()
    {
        ItemContainer worn = client.getItemContainer(InventoryID.WORN);
        ItemContainer inv = client.getItemContainer(InventoryID.INV);

        if (worn != null)
        {
            for (Item item : worn.getItems())
            {
                SkillItem skillItem = SkillItem.fromId(item.getId());
                if (skillItem != null && skillItem.getSkillOp() == SkillOp.HARPOON)
                {
                    return true;
                }
            }
        }

        if (inv != null)
        {
            for (Item item : inv.getItems())
            {
                SkillItem skillItem = SkillItem.fromId(item.getId());
                if (skillItem != null && skillItem.getSkillOp() == SkillOp.HARPOON)
                {
                    return true;
                }
            }
        }

        return false;
    }
}

package com.choiceman.menus;

import lombok.Getter;
import net.runelite.api.gameval.ItemID;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Maps blighted sack items to the spells they enable and provides
 * a fast lookup from spell name → corresponding sack.
 */
@Getter
public enum BlightedSack {
    ENTANGLE(
            ItemID.BLIGHTED_SACK_ENTANGLE,
            Set.of("Snare", "Entangle", "Bind")
    ),
    SURGE(
            ItemID.BLIGHTED_SACK_SURGE,
            Set.of(
                    "Wind Surge", "Water Surge", "Earth Surge", "Fire Surge",
                    "Wind Wave", "Water Wave", "Earth Wave", "Fire Wave"
            )
    ),
    TELEBLOCK(
            ItemID.BLIGHTED_SACK_TELEBLOCK,
            Set.of("Tele Block", "Teleport to Target")
    ),
    VENGEANCE(
            ItemID.BLIGHTED_SACK_VENGEANCE,
            Set.of("Vengeance", "Vengeance Other")
    ),
    ANCIENT_ICE(
            ItemID.BLIGHTED_SACK_ICEBARRAGE,
            Set.of("Ice Rush", "Ice Burst", "Ice Blitz", "Ice Barrage")
    );

    private static final Map<String, BlightedSack> SPELL_TO_SACK;

    static {
        // Build an immutable lookup for O(1) spell → sack resolution.
        Map<String, BlightedSack> map = new HashMap<>();
        for (BlightedSack sack : values()) {
            for (String spell : sack.allowedSpells) {
                map.put(spell, sack);
            }
        }
        SPELL_TO_SACK = Map.copyOf(map);
    }

    private final int sackItemId;
    private final Set<String> allowedSpells;

    BlightedSack(int sackItemId, Set<String> allowedSpells) {
        this.sackItemId = sackItemId;
        this.allowedSpells = allowedSpells;
    }

    /**
     * Returns the sack that grants the given spell, or {@code null} if none.
     */
    public static BlightedSack fromSpell(String spellName) {
        return SPELL_TO_SACK.get(spellName);
    }
}

