    MYSTIC_STEAM_STAFF_OR(true, ItemID.MYSTIC_STEAM_BATTLESTAFF_PRETTY, WATER_RUNE, FIRE_RUNE),
    LAVA_STAFF(true, ItemID.LAVA_BATTLESTAFF, EARTH_RUNE, FIRE_RUNE),
    LAVA_STAFF_OR(true, ItemID.LAVA_BATTLESTAFF_PRETTY, EARTH_RUNE, FIRE_RUNE),
    MYSTIC_LAVA_STAFF(true, ItemID.MYSTIC_LAVA_STAFF, EARTH_RUNE, FIRE_RUNE),
    MYSTIC_LAVA_STAFF_OR(true, ItemID.MYSTIC_LAVA_STAFF_PRETTY, EARTH_RUNE, FIRE_RUNE),
    TWINFLAME_STAFF(true, ItemID.TWINFLAME_STAFF, WATER_RUNE, FIRE_RUNE),
    BRYOPHYTAS_STAFF_CHARGED(
            true,
            ItemID.NATURE_STAFF_CHARGED,
            ItemID.NATURE_STAFF_UNCHARGED,
            NATURE_RUNE
    );

    private final boolean requiresEquipped;
    private final int id;
    private final int unlockItemId;
    private final HashSet<Integer> provides = new HashSet<>();

    RuneProvider(int id)
    {
        this.requiresEquipped = false;
        this.id = id;
        this.unlockItemId = id;
        this.provides.add(id);
    }

    RuneProvider(boolean requiresEquipped, int id, RuneProvider... provides)
    {
        this(requiresEquipped, id, id, provides);
    }

    RuneProvider(boolean requiresEquipped, int id, int unlockItemId, RuneProvider... provides)
    {
        this.requiresEquipped = requiresEquipped;
        this.id = id;
        this.unlockItemId = unlockItemId;

        for (RuneProvider runeProvider : provides)
        {
            this.provides.addAll(runeProvider.getProvides());
        }
    }

    private static final HashSet<Integer> EQUIPPED_PROVIDERS = new HashSet<>();
    private static final HashSet<Integer> INV_PROVIDERS = new HashSet<>();
    private static final HashMap<Integer, HashSet<Integer>> PROVIDER_TO_PROVIDED = new HashMap<>();
    private static final HashMap<Integer, RuneProvider> ID_TO_PROVIDER = new HashMap<>();

    static
    {
        for (RuneProvider runeProvider : RuneProvider.values())
        {
            PROVIDER_TO_PROVIDED.put(runeProvider.getId(), runeProvider.getProvides());
            ID_TO_PROVIDER.put(runeProvider.getId(), runeProvider);

            if (runeProvider.isRequiresEquipped())
            {
                EQUIPPED_PROVIDERS.add(runeProvider.getId());
            }
            else
            {
                INV_PROVIDERS.add(runeProvider.getId());
            }
        }
    }

    public static boolean isEquippedProvider(int id)
    {
        return EQUIPPED_PROVIDERS.contains(id);
    }

    public static boolean isInvProvider(int id)
    {
        return INV_PROVIDERS.contains(id);
    }

    public static HashSet<Integer> getProvidedRunes(int id)
    {
        HashSet<Integer> provided = PROVIDER_TO_PROVIDED.get(id);
        return provided == null ? new HashSet<>() : provided;
    }

    public static RuneProvider fromId(int id)
    {
        return ID_TO_PROVIDER.get(id);
    }
}

package com.choiceman.menus;

import lombok.Getter;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;

/**
 * Canonical set of tool/skill menu options the plugin understands.
 * <p>
 * Lookups use the exact menu option text as displayed by the client.
 */
@Getter
public enum SkillOp
{
    CHOP_DOWN("Chop down"),
    MINE("Mine"),
    SMALL_NET("Small Net"),
    BIG_NET("Big Net"),
    CAGE("Cage"),
    BAIT("Bait"),
    LURE("Lure"),
    HARPOON("Harpoon"),
    RAKE("Rake"),
    PRUNE("Prune"),
    CURE("Cure"),
    GRIND("Grind"),
    SMITH("Smith"),
    SMELT("Smelt"),
    SHEAR("Shear"),
    CLEAN("Clean"),
    FIRE("Fire"),
    CRAFT_RUNE("Craft-rune");

    private final String option;

    SkillOp(String option)
    {
        this.option = option;
    }

    private static final HashSet<String> ALL_SKILL_OPS = new HashSet<>();
    private static final HashMap<String, SkillOp> STRING_TO_OP = new HashMap<>();

    static
    {
        for (SkillOp skillOp : SkillOp.values())
        {
            ALL_SKILL_OPS.add(skillOp.option);
            STRING_TO_OP.put(skillOp.option, skillOp);
        }
    }

    public static boolean isSkillOp(String option)
    {
        return ALL_SKILL_OPS.contains(option);
    }

    public static SkillOp fromString(String option)
    {
        if (!isSkillOp(option)) return null;
        return STRING_TO_OP.get(option);
    }
}

package com.choiceman.ui;

import com.choiceman.data.ItemsRepository;
import net.runelite.client.game.ItemManager;

import java.awt.*;
import java.awt.font.GlyphVector;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.util.function.Supplier;

/**
 * Renders Choice Man "card" UI elements: background, icon, name text, hover/selection
 * borders and glow, and the minimize/restore pills. Stateless aside from the provided
 * {@link Supplier} for an accent color, so a single instance can be reused.
 */
final class CardRenderer {

    private static final int ICON_W = 28, ICON_H = 28;
    private static final float NAME_FONT_SIZE = 15.5f;
    private static final int NAME_MAX_LINES = 2, NAME_SIDE_PADDING = 8, NAME_LINE_SPACING = 0;

    /**
     * Stable FontRenderContext used for text wrapping/measurement independent of the
     * current {@link Graphics2D} transform. This avoids reflow when the card is scaled.
     */
    private static final java.awt.font.FontRenderContext BASE_FRC =
            new java.awt.font.FontRenderContext(null, /*antialias*/true, /*fractional*/true);

    private final Supplier<Color> accentSupplier;

    /**
     * @param accentSupplier supplier for the current accent color used in borders/glows.
     */
    CardRenderer(Supplier<Color> accentSupplier) {
        this.accentSupplier = accentSupplier;
    }

    /**
     * Draws an inner radial glow used during selection emphasis.
     *
     * @param g   graphics context
     * @param r   card bounds (local to card transform)
     * @param t   normalized intensity [0..1]
     * @param acc accent color
     */
    private static void drawSelectedGlowInside(Graphics2D g, Rectangle r, float t, Color acc) {
        t = clamp01(t);
        final int cx = r.x + r.width / 2;
        final int cy = r.y + r.height / 2 - 6;
        final float radius = Math.min(r.width, r.height) * 0.52f;
        final int corner = 12;

        Paint oldPaint = g.getPaint();
        Composite oldComp = g.getComposite();

        RadialGradientPaint rg = new RadialGradientPaint(
                new Point(cx, cy), radius,
                new float[]{0f, 0.35f, 1f},
                new Color[]{
                        new Color(acc.getRed(), acc.getGreen(), acc.getBlue(), (int) (150 * t)),
                        new Color(acc.getRed(), acc.getGreen(), acc.getBlue(), (int) (60 * t)),
                        new Color(acc.getRed(), acc.getGreen(), acc.getBlue(), 0)
                }
        );

        g.setComposite(AlphaComposite.SrcOver);
        g.setPaint(rg);
        g.fillRoundRect(r.x + 2, r.y + 2, r.width - 4, r.height - 4, corner, corner);

        Stroke sOld = g.getStroke();
        g.setStroke(new BasicStroke(1.2f));
        g.setColor(new Color(255, 255, 255, (int) (38 * t)));
        g.drawRoundRect(r.x + 3, r.y + 3, r.width - 6, r.height - 6, corner - 2, corner - 2);

        g.setStroke(sOld);
        g.setPaint(oldPaint);
        g.setComposite(oldComp);
    }

    /**
     * Draws a gradient ring + subtle outer glow around the card. Used for hover and selection.
     *
     * @param g   graphics context
     * @param r   card bounds (local to card transform)
     * @param t01 normalized visibility [0..1]
     * @param acc accent color
     */
    private static void drawFancyBorder(Graphics2D g, Rectangle r, float t01, Color acc) {
        t01 = clamp01(t01);
        final int arc = 12, innerInset = 2, ringOutset = 2, glowPasses = 2;

        Paint oldPaint = g.getPaint();
        Stroke oldStroke = g.getStroke();
        Composite oldComp = g.getComposite();

        var outer = new java.awt.geom.RoundRectangle2D.Float(r.x - ringOutset, r.y - ringOutset,
                r.width + ringOutset * 2, r.height + ringOutset * 2, arc + ringOutset * 2, arc + ringOutset * 2);
        var inner = new java.awt.geom.RoundRectangle2D.Float(r.x + innerInset, r.y + innerInset,
                r.width - innerInset * 2, r.height - innerInset * 2, Math.max(2, arc - 2), Math.max(2, arc - 2));
        var ring = new java.awt.geom.Area(outer);
        ring.subtract(new java.awt.geom.Area(inner));

        float[] stops = {0f, .5f, 1f};
        Color cTop = new Color(acc.getRed(), acc.getGreen(), acc.getBlue(), (int) (200 * t01));
        Color cMid = new Color(acc.getRed(), acc.getGreen(), acc.getBlue(), (int) (160 * t01));
        Color cBot = new Color(acc.getRed(), acc.getGreen(), acc.getBlue(), (int) (200 * t01));
        var lg = new java.awt.LinearGradientPaint(r.x, r.y, r.x, r.y + r.height, stops, new Color[]{cTop, cMid, cBot});
        g.setPaint(lg);
        g.setComposite(AlphaComposite.SrcOver);
        g.fill(ring);

        for (int i = 1; i <= glowPasses; i++) {
            float falloff = (glowPasses - (i - 1)) / (float) glowPasses;
            int a = (int) (60 * falloff * t01);
            if (a <= 0) continue;
            var glowOuter = new java.awt.geom.RoundRectangle2D.Float(
                    r.x - (ringOutset + i), r.y - (ringOutset + i),
                    r.width + (ringOutset + i) * 2, r.height + (ringOutset + i) * 2,
                    arc + (ringOutset + i) * 2, arc + (ringOutset + i) * 2
            );
            var glowRing = new java.awt.geom.Area(glowOuter);
            glowRing.subtract(new java.awt.geom.Area(outer));
            g.setPaint(new Color(acc.getRed(), acc.getGreen(), acc.getBlue(), a));
            g.fill(glowRing);
        }
        g.setStroke(new BasicStroke(1f));
        g.setColor(new Color(255, 255, 255, (int) (36 * t01)));
        g.draw(new java.awt.geom.RoundRectangle2D.Float(r.x + 2, r.y + 2, r.width - 4, r.height - 4, Math.max(1, arc - 4), Math.max(1, arc - 4)));

        g.setPaint(oldPaint);
        g.setStroke(oldStroke);
        g.setComposite(oldComp);
    }

    /**
     * Clamps a float to the [0..1] range.
     *
     * @param f value
     * @return clamped value
     */
    static float clamp01(float f) {
        return f < 0 ? 0 : (f > 1 ? 1 : f);
    }

    /**
     * Draws a single choice card with optional hover/selection styling.
     * Handles text wrapping using a stable {@link java.awt.font.FontRenderContext} so that
     * scaling the card doesn't change line breaks.
     *
     * @param g           graphics context
     * @param card        card rectangle in overlay-local space
     * @param base        base name to render under the icon
     * @param hovered     whether to show the hover border
     * @param alpha       overall opacity [0..1]
     * @param scale       uniform scale factor for the card
     * @param glowT       selection-emphasis intensity [0..1] (used by inner glow)
     * @param emphasize   whether this card is the selected one (adds inner glow and stronger border)
     * @param bg          background image to draw behind content; if null, a flat style is used
     * @param itemManager RuneLite ItemManager for loading the icon image
     * @param repo        repository to resolve item IDs from the base name
     * @param accent      supplier of accent color for borders/glow
     */
    void drawCard(Graphics2D g, Rectangle card, String base, boolean hovered,
                  float alpha, float scale, float glowT, boolean emphasize,
                  BufferedImage bg, ItemManager itemManager, ItemsRepository repo,
                  Supplier<Color> accent) {
        if (card == null) return;

        // measure/wrap text against a stable (identity) FRC BEFORE any scaling
        final Font nameFont = g.getFont().deriveFont(Font.BOLD, NAME_FONT_SIZE);
        final int maxTextWidth = card.width - (NAME_SIDE_PADDING * 2);

        java.util.function.ToIntFunction<String> measure = s -> {
            if (s == null || s.isEmpty()) return 0;
            return (int) Math.ceil(nameFont.getStringBounds(s, BASE_FRC).getWidth());
        };

        java.util.List<String> lines = new java.util.ArrayList<>(NAME_MAX_LINES);
        {
            String text = (base == null) ? "" : base.trim();
            if (measure.applyAsInt(text) <= maxTextWidth || !text.contains(" ")) {
                if (measure.applyAsInt(text) > maxTextWidth) {
                    String ell = "…";
                    while (!text.isEmpty() && measure.applyAsInt(text + ell) > maxTextWidth) {
                        text = text.substring(0, text.length() - 1);
                    }
                    text = text + ell;
                }
                lines.add(text);
            } else {
                String[] words = text.split("\\s+");
                StringBuilder line = new StringBuilder();
                for (String w : words) {
                    String next = (line.length() == 0) ? w : line + " " + w;
                    if (measure.applyAsInt(next) <= maxTextWidth) {
                        line.setLength(0);
                        line.append(next);
                    } else {
                        if (line.length() == 0) {
                            String ell = "…";
                            String ww = w;
                            while (!ww.isEmpty() && measure.applyAsInt(ww + ell) > maxTextWidth) {
                                ww = ww.substring(0, ww.length() - 1);
                            }
                            lines.add(ww + ell);
                        } else {
                            lines.add(line.toString());
                            line = new StringBuilder(w);
                        }
                        if (lines.size() == NAME_MAX_LINES) {
                            String last = lines.get(lines.size() - 1);
                            String rem = (line.length() == 0) ? "" : (" " + line);
                            String candidate = last + rem;
                            String ell = "…";
                            while (!candidate.isEmpty() && measure.applyAsInt(candidate + ell) > maxTextWidth) {
                                candidate = candidate.substring(0, candidate.length() - 1);
                            }
                            lines.set(lines.size() - 1, candidate + ell);
                            break;
                        }
                    }
                }
                if (lines.size() < NAME_MAX_LINES && line.length() > 0) {
                    if (measure.applyAsInt(line.toString()) <= maxTextWidth) {
                        lines.add(line.toString());
                    } else {
                        String s = line.toString();
                        String ell = "…";
                        while (!s.isEmpty() && measure.applyAsInt(s + ell) > maxTextWidth) {
                            s = s.substring(0, s.length() - 1);
                        }
                        lines.add(s + ell);
                    }
                }
            }
        }

        FontMetrics nfm = g.getFontMetrics(nameFont);

        int iconW = ICON_W, iconH = ICON_H;
        int anyId = (repo != null) ? repo.getIdsForBase(base).stream().findFirst().orElse(0) : 0;
        BufferedImage img = (itemManager != null && anyId > 0) ? itemManager.getImage(anyId) : null;
        if (img != null) {
            int srcW = Math.max(1, img.getWidth()), srcH = Math.max(1, img.getHeight());
            int maxIconW = card.width - (NAME_SIDE_PADDING * 2);
            int scaleInt = (srcW * 2 <= maxIconW) ? 2 : 1;
            iconW = srcW * scaleInt;
            iconH = srcH * scaleInt;
        }

        final int spacing = 6;
        final int lineH = nfm.getHeight() + NAME_LINE_SPACING;
        final int textBlockH = lines.size() * lineH - NAME_LINE_SPACING;
        final int contentH = iconH + spacing + textBlockH;
        final int topY = (card.height - contentH) / 2;

        Composite oldComp = g.getComposite();
        AffineTransform oldTx = g.getTransform();

        int cx = card.x + card.width / 2, cy = card.y + card.height / 2;
        g.translate(cx, cy);
        g.scale(scale, scale);
        g.translate(-card.width / 2.0, -card.height / 2.0);
        g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, CardRenderer.clamp01(alpha)));

        if (bg != null) {
            g.setColor(new Color(0, 0, 0, Math.min(180, (int) (120 * alpha))));
            g.fillRoundRect(2, 4, card.width, card.height, 16, 16);
            g.drawImage(bg, 0, 0, card.width, card.height, null);
        } else {
            g.setColor(new Color(26, 26, 26, Math.min(255, (int) (232 * alpha))));
            g.fillRoundRect(0, 0, card.width, card.height, 14, 14);
            g.setColor(new Color(96, 96, 96, Math.min(255, (int) (220 * alpha))));
            g.drawRoundRect(0, 0, card.width, card.height, 14, 14);
        }

        if (emphasize) {
            drawSelectedGlowInside(g, new Rectangle(0, 0, card.width, card.height),
                    CardRenderer.clamp01(glowT), accent.get());
        }
        if (hovered || emphasize) {
            float t = hovered ? 1f : Math.min(1f, 0.60f + glowT);
            drawFancyBorder(g, new Rectangle(0, 0, card.width, card.height), t, accent.get());
        }

        if (img != null) {
            int ix = (card.width - iconW) / 2, iy = topY;
            Object prevInterp = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
            try {
                boolean integerMultiple = (iconW % Math.max(1, img.getWidth()) == 0) &&
                        (iconH % Math.max(1, img.getHeight()) == 0);
                g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
                        integerMultiple ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR
                                : RenderingHints.VALUE_INTERPOLATION_BICUBIC);
                g.drawImage(img, ix, iy, iconW, iconH, null);
            } finally {
                if (prevInterp != null) g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, prevInterp);
            }
        }

        g.setFont(nameFont);
        int baseline = topY + iconH + spacing + nfm.getAscent();
        Object prevFM = g.getRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS);
        g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_ON);

        for (String line : lines) {
            int sw = nfm.stringWidth(line), tx = (card.width - sw) / 2;
            GlyphVector gv = nameFont.createGlyphVector(g.getFontRenderContext(), line);
            Shape textShape = gv.getOutline();

            AffineTransform preTx = g.getTransform();
            Composite preComp = g.getComposite();
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, CardRenderer.clamp01(alpha)));
            g.translate(tx, baseline);

            g.translate(2, 2);
            g.setColor(new Color(0, 0, 0, 235));
            g.fill(textShape);
            g.translate(-2, -2);
            int[][] feather = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
            for (int[] o : feather) {
                g.translate(o[0], o[1]);
                g.setColor(new Color(0, 0, 0, 180));
                g.fill(textShape);
                g.translate(-o[0], -o[1]);
            }

            g.setColor(new Color(255, 255, 255, Math.min(255, (int) (255 * alpha))));
            g.fill(textShape);
            g.setTransform(preTx);
            g.setComposite(preComp);
            baseline += lineH;
        }
        if (prevFM != null)
            g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, prevFM);

        g.setTransform(oldTx);
        g.setComposite(oldComp);
    }

    /**
     * Draws the title image (or a text fallback) and returns the y-position where cards should
     * start rendering below the title block.
     *
     * @param g      graphics context
     * @param title  title image (nullable). If null, a text fallback is used.
     * @param availW viewport width for centering
     * @param topY   top y-coordinate to place the title
     * @param gapY   extra vertical gap under the title
     * @param pullUp negative offset to pull cards up into the title a bit
     * @return y-position for the first row of cards
     */
    int drawTitle(Graphics2D g, BufferedImage title, int availW, int topY, int gapY, int pullUp) {
        if (title != null) {
            int drawX = Math.max(0, (availW - title.getWidth()) / 2);
            g.drawImage(title, drawX, topY, null);
            return topY + title.getHeight() + gapY - pullUp;
        }
        g.setFont(g.getFont().deriveFont(Font.BOLD, 16f));
        g.setColor(Color.WHITE);
        String s = "Choose your unlock";
        int sw = g.getFontMetrics().stringWidth(s);
        g.drawString(s, Math.max(0, (availW - sw) / 2), topY + 16);
        return topY + 24 + gapY - pullUp;
    }

    /**
     * Draws the top-right minimize pill and returns its hitbox for input.
     *
     * @param g       graphics context
     * @param w       pill width
     * @param h       pill height
     * @param label   button label
     * @param hovered whether to render hover state
     * @param acc     accent color supplier
     * @return rectangle bounds of the pill for hit testing
     */
    Rectangle drawMinimizePillAt(Graphics2D g, int x, int y, int w, int h,
                                 String label, boolean hovered, Supplier<Color> acc) {
        g.setColor(new Color(26, 26, 26, 220));
        g.fillRoundRect(x, y, w, h, 10, 10);
        Color a = acc.get();
        if (hovered) {
            a = new Color(a.getRed(), a.getGreen(), a.getBlue(),
                    Math.min(255, (int) (a.getAlpha() * 1.1)));
        }

        Stroke s = g.getStroke();
        g.setStroke(new BasicStroke(1.8f));
        g.setColor(a);
        g.drawRoundRect(x, y, w, h, 10, 10);
        g.setStroke(s);
        g.setFont(g.getFont().deriveFont(Font.BOLD, 12f));
        g.setColor(Color.WHITE);
        FontMetrics fm = g.getFontMetrics();

        g.drawString(label,
                x + (w - fm.stringWidth(label)) / 2,
                y + ((h - fm.getHeight()) / 2) + fm.getAscent());

        return new Rectangle(x, y, w, h);
    }

    /**
     * Draws the centered restore pill used when the presentation is minimized, and returns
     * the painted extent to help layout upstream overlays.
     *
     * @param g            graphics context
     * @param viewportW    viewport width for centering
     * @param rootY        top y-position
     * @param w            pill width
     * @param h            pill height
     * @param pendingCount number of queued presentations to show beside the label (optional)
     * @param outBounds    consumer that receives the hitbox rectangle
     * @param acc          accent color supplier
     * @param hovered      whether to render hover state
     * @return rendered area extent (width of viewport, and height up to the pill bottom)
     */
    Dimension drawRestorePill(Graphics2D g, int viewportW, int rootY, int w, int h,
                              int pendingCount, java.util.function.Consumer<Rectangle> outBounds,
                              Supplier<Color> acc, boolean hovered) {
        int x = Math.max(8, (viewportW - w) / 2), y = rootY;
        outBounds.accept(new Rectangle(x, y, w, h));
        g.setColor(new Color(26, 26, 26, 232));
        g.fillRoundRect(x, y, w, h, 12, 12);
        Color a = acc.get();
        if (hovered) a = new Color(a.getRed(), a.getGreen(), a.getBlue(), Math.min(255, (int) (a.getAlpha() * 1.1)));
        Stroke s = g.getStroke();
        g.setStroke(new BasicStroke(2f));
        g.setColor(a);
        g.drawRoundRect(x, y, w, h, 12, 12);
        g.setStroke(s);
        g.setFont(g.getFont().deriveFont(Font.BOLD, 13f));
        g.setColor(Color.WHITE);
        String label = pendingCount > 0 ? ("Show choices (" + pendingCount + ")") : "Show choices";
        FontMetrics fm = g.getFontMetrics();
        g.drawString(label, x + (w - fm.stringWidth(label)) / 2, y + ((h - fm.getHeight()) / 2) + fm.getAscent());
        return new Dimension(viewportW, h + rootY + 8);
    }

    /**
     * Enables antialiasing for shapes and text. Call at the start of a paint pass.
     *
     * @param g graphics context
     */
    void enableAA(Graphics2D g) {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
    }

    /**
     * Simple text-wrapping utilities used by older call-sites. The main card rendering path
     * uses a BASE_FRC-based wrapper to keep line breaks stable across transforms, but this
     * helper remains available when a {@link FontMetrics} based approach is sufficient.
     */
    static final class TextWrap {
        /**
         * Greedy wrap into up to {@code maxLines} lines, ellipsizing the last line if needed.
         *
         * @param text     text to wrap
         * @param fm       font metrics to measure width
         * @param maxWidth maximum width in pixels per line
         * @param maxLines maximum number of lines to emit
         * @return list of wrapped lines (size 1..maxLines). Empty input produces a single empty line.
         */
        static java.util.List<String> wrap(String text, FontMetrics fm, int maxWidth, int maxLines) {
            java.util.List<String> out = new java.util.ArrayList<>();
            if (text == null || text.isEmpty() || fm.stringWidth(text) <= maxWidth) {
                out.add(text == null ? "" : text);
                return out;
            }
            String[] words = text.split("\\s+");
            StringBuilder line = new StringBuilder();
            for (String w : words) {
                String next = (line.length() == 0) ? w : line + " " + w;
                if (fm.stringWidth(next) <= maxWidth) {
                    line.setLength(0);
                    line.append(next);
                } else {
                    if (line.length() == 0) out.add(hardBreak(w, fm, maxWidth));
                    else {
                        out.add(line.toString());
                        if (fm.stringWidth(w) > maxWidth) out.add(hardBreak(w, fm, maxWidth));
                        else line = new StringBuilder(w);
                    }
                    if (out.size() == maxLines) {
                        String last = out.get(out.size() - 1);
                        out.set(out.size() - 1, ellipsize(last + (line.length() == 0 ? "" : " " + line), fm, maxWidth));
                        return out;
                    }
                }
            }
            if (line.length() > 0) {
                if (out.size() < maxLines) out.add(line.toString());
                else {
                    String last = out.get(out.size() - 1);
                    out.set(out.size() - 1, ellipsize(last + " " + line, fm, maxWidth));
                }
            }
            return out;
        }

        /**
         * Breaks a single long word to fit, appending an ellipsis when truncated.
         */
        private static String hardBreak(String word, FontMetrics fm, int maxWidth) {
            if (fm.stringWidth(word) <= maxWidth) return word;
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < word.length(); i++) {
                sb.append(word.charAt(i));
                if (fm.stringWidth(sb.toString() + "…") > maxWidth) {
                    if (sb.length() > 1) sb.setLength(sb.length() - 1);
                    sb.append("…");
                    break;
                }
            }
            return sb.toString();
        }

        /**
         * Ellipsizes a string to fit within {@code maxWidth} using the supplied metrics.
         */
        private static String ellipsize(CharSequence s, FontMetrics fm, int maxWidth) {
            String str = s.toString().trim();
            if (fm.stringWidth(str) <= maxWidth) return str;
            String ell = "…";
            while (str.length() > 0 && fm.stringWidth(str + ell) > maxWidth) str = str.substring(0, str.length() - 1);
            return str + ell;
        }
    }
}

package com.choiceman.ui;

import com.choiceman.ChoiceManConfig;
import com.choiceman.data.ChoiceManUnlocks;
import com.choiceman.data.ItemsRepository;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import java.util.*;
import java.util.List;

/**
 * Overlay responsible for rendering and interacting with Choice Man's “pick an unlock” UI.
 * <p>
 * Features:
 * <ul>
 *   <li>Animated sequential reveal of cards with hover/select SFX.</li>
 *   <li>Optional “milestone” gold background styling per presentation.</li>
 *   <li>Minimize/restore pill with pending count when multiple picks are queued.</li>
 *   <li>Strict, idempotent presentation lifecycle: {@link #presentChoicesSequential(List, boolean)} → (animations) → {@link #dismiss()}.</li>
 * </ul>
 * Threading & state:
 * <ul>
 *   <li>All rendering executes on RuneLite's overlay paint thread via {@link #render(Graphics2D)}.</li>
 *   <li>User input is handled by a local {@link MouseAdapter} returned from {@link #getMouseAdapter()}.</li>
 *   <li>Volatile fields guard render/input races; UI mutations are intentionally lightweight.</li>
 * </ul>
 */
@Singleton
public class ChoiceManOverlay extends Overlay {
    /**
     * Top padding for the overlay root; used to position title and cards.
     */
    private static final int ROOT_Y = 32, TITLE_GAP_Y = 8;

    /**
     * Card dimensions and horizontal/vertical spacing.
     */
    private static final int CARD_W = 140, CARD_H = 130, CARD_GAP = 12;

    /**
     * Dimensions for the minimize button (top-right pill).
     */
    private static final int MIN_BTN_W = 92, MIN_BTN_H = 22;

    /**
     * Dimensions for the restore pill (shown while minimized).
     */
    private static final int RESTORE_W = 170, RESTORE_H = 28;

    /**
     * Subtle per-row upward lift to create a stacked look.
     */
    private static final int LIFT_PER_ROW = 10;

    /**
     * Default timings (ms) for popup reveal and selection animation phases.
     */
    private static final int POP_REVEAL_MS = 420, EXPLODE_MS = 650;
    private static final int SEL_MOVE_MS = 700, SEL_HOLD_MS = 220, SEL_FADE_MS = 520;

    /**
     * Total time of the select sequence: explode → move → hold → fade.
     */
    private static final int ANIM_TOTAL = EXPLODE_MS + SEL_MOVE_MS + SEL_HOLD_MS + SEL_FADE_MS;

    /**
     * Title placement fine-tuning.
     */
    private static final int TITLE_TOP_Y = 0, CARDS_PULL_UP_Y = 9;

    private final Client client;
    private final EventBus eventBus;
    private final CardRenderer renderer;
    private final PickAnimationEngine anim;
    // Card layout bookkeeping
    private final List<Rectangle> cardBounds = new ArrayList<>();
    private final Object boundsLock = new Object();
    // SFX gating (play once per card)
    private final Set<Integer> popupPlayed = Collections.synchronizedSet(new HashSet<>());
    private ItemManager itemManager;
    private ItemsRepository repo;
    private ChoiceManUnlocks unlocks;
    private BufferedImage titleImg, cardBgDefault, cardBgGold;
    public static final class ChoicesPresentedEvent {}
    /**
     * If true, use milestone (gold) card background for the current presentation.
     */
    private volatile boolean useGoldBgThisPresentation = false;
    @Setter
    private ChoiceManConfig config;
    /**
     * Callback invoked when the user selects a base (card). Receives the selected base name.
     */
    @Setter
    private java.util.function.Consumer<String> onPick;
    /**
     * Callback invoked after the presentation fully dismisses (post-selection or manual dismiss).
     */
    @Setter
    private Runnable onDismiss;
    /**
     * Whether a presentation is currently visible (not minimized) or minimized.
     */
    @Getter
    private volatile boolean active = false;
    // Runtime presentation state
    private volatile List<String> choices;
    @Getter
    private volatile Instant presentedAt;
    private volatile int hoveredIndex = -1, lastHoverIndex = -1;
    @Getter
    private volatile boolean minimized = false;
    private volatile int pendingCount = 0; // number of queued picks; shown in the restore pill
    // Hit-test rectangles for controls
    private Rectangle minimizeBounds = null, restoreBounds = null;
    private volatile boolean hoverMinimize = false, hoverRestore = false;
    // Selection animation state
    private volatile boolean animating = false;
    private volatile int selectedIndex = -1;
    private volatile Instant animStart = null;
    private volatile boolean pickSent = false;
    private volatile boolean[] fullyRevealed = new boolean[0];
    /**
     * Input handler for hover/select and minimize/restore interactions.
     * <p>
     * All coordinates are translated to overlay-local space to match render-time layout.
     */
    private final MouseAdapter mouse = new MouseAdapter() {
        private Point toOverlayLocal(MouseEvent e) {
            Rectangle ob = getBounds();
            return (ob == null) ? null : new Point(e.getX() - ob.x, e.getY() - ob.y);
        }

        @Override
        public MouseEvent mouseMoved(MouseEvent e) {
            if (!active || choices == null || choices.isEmpty() || animating) return e;
            Point lp = toOverlayLocal(e);
            if (lp == null) return e;

            if (minimized) {
                hoverRestore = restoreBounds != null && restoreBounds.contains(lp);
                hoveredIndex = -1;
                hoverMinimize = false;
            } else {
                int newHover = indexAt(lp);
                if (!isCardFullyRevealed(newHover)) newHover = -1;
                if (newHover != hoveredIndex) hoveredIndex = newHover;
                if (hoveredIndex >= 0 && hoveredIndex != lastHoverIndex) anim.playHover();
                lastHoverIndex = hoveredIndex;
                hoverMinimize = minimizeBounds != null && minimizeBounds.contains(lp);
                hoverRestore = false;
            }
            return e;
        }

        @Override
        public MouseEvent mousePressed(MouseEvent e) {
            if (!active || choices == null || choices.isEmpty() || animating) return e;
            if (e.getButton() != MouseEvent.BUTTON1) return e;
            Point lp = toOverlayLocal(e);
            if (lp == null) return e;

            if (minimized && restoreBounds != null && restoreBounds.contains(lp)) {
                setMinimized(false);
                e.consume();
                return e;
            }
            if (!minimized && minimizeBounds != null && minimizeBounds.contains(lp)) {
                setMinimized(true);
                e.consume();
                return e;
            }
            if (minimized) return e;

            int idx = indexAt(lp);
            if (!isCardFullyRevealed(idx)) return e;

            if (idx >= 0 && idx < choices.size()) {
                anim.playSelect();
                selectedIndex = idx;
                animating = true;
                animStart = Instant.now();
                anim.resetParticles();
                hoveredIndex = -1;
                lastHoverIndex = -1;
                e.consume();
            }
            return e;
        }
    };

    /**
     * Constructs the overlay and sets its position/layer.
     * The overlay paints above game widgets at the top center of the viewport.
     *
     * @param client RuneLite client (used for viewport size).
     */
    @Inject
    public ChoiceManOverlay(Client client, EventBus eventBus, AudioPlayer audioPlayer) {
        this.client = client;
        this.eventBus = eventBus;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        this.renderer = new CardRenderer(this::getAccent);
        this.anim = new PickAnimationEngine(audioPlayer);
    }

    /**
     * Programmatically minimize or restore the overlay.
     */
    public void setMinimized(boolean value) {
        if (!active || choices == null || choices.isEmpty()) return;
        if (minimized == value) return;
        if (value) {
            minimized = true;
            hoveredIndex = -1;
            lastHoverIndex = -1;
            return;
        }
        minimized = false;
        presentedAt = Instant.now();
        popupPlayed.clear();
        fullyRevealed = (choices != null) ? new boolean[choices.size()] : new boolean[0];
        hoveredIndex = -1;
        lastHoverIndex = -1;
        animating = false;
        selectedIndex = -1;
        animStart = null;
        pickSent = false;
        anim.resetParticles();
    }

    /**
     * @return The mouse listener to register with the {@code MouseManager}
     * when enabling the overlay, and unregister on disable.
     */
    public MouseListener getMouseAdapter() {
        return mouse;
    }

    /**
     * Update the count shown on the minimized/restore pill.
     * Has no visual effect when the overlay is fully visible.
     *
     * @param count queued pick count (clamped at 0+).
     */
    public void setPendingCount(int count) {
        pendingCount = Math.max(0, count);
    }

    /**
     * Load images and initialize audio assets for the overlay.
     * Must be called before presenting choices.
     *
     * @param bgPathDefault path to the default card background.
     * @param bgPathGold    path to the milestone (gold) card background.
     * @param itemManager   RuneLite item manager for icons/IDs.
     * @param repo          repository mapping base names to item IDs and metadata.
     * @param unlocks       unlock state (used for rendering obtained/unlocked visuals if needed).
     */
    public void setAssets(String bgPathDefault, String bgPathGold,
                          ItemManager itemManager, ItemsRepository repo, ChoiceManUnlocks unlocks) {
        this.cardBgDefault = ImageUtil.loadImageResource(getClass(), bgPathDefault);
        this.cardBgGold = ImageUtil.loadImageResource(getClass(), bgPathGold);
        this.titleImg = ImageUtil.loadImageResource(getClass(), "/com/choiceman/ui/Unlock_an_Item.png");
        this.itemManager = itemManager;
        this.repo = repo;
        this.unlocks = unlocks;

        anim.loadSfx(
        );
        if (config != null) setSfxVolumePercent(config.sfxVolume());
    }

    /**
     * Sets SFX volume (0–100).
     *
     * @param percent percentage (0 = muted, 100 = full volume).
     */
    public void setSfxVolumePercent(int percent) {
        anim.setVolumePercent(percent);
    }

    /**
     * Begins a new pick presentation with the provided list of base names.
     * Cards reveal in sequence with a small per-card delay. If {@code milestone} is true,
     * cards use the gold background for this presentation only.
     *
     * @param bases     ordered list of base names to present as choices (1–5 typical).
     * @param milestone whether to render with milestone (gold) styling.
     */
    public void presentChoicesSequential(List<String> bases, boolean milestone) {
        this.useGoldBgThisPresentation = milestone;
        this.choices = bases;
        this.presentedAt = Instant.now();
        this.active = true;
        this.minimized = false;

        hoveredIndex = -1;
        lastHoverIndex = -1;
        hoverMinimize = hoverRestore = false;
        minimizeBounds = restoreBounds = null;

        animating = false;
        selectedIndex = -1;
        animStart = null;
        pickSent = false;
        anim.resetAll();
        popupPlayed.clear();

        synchronized (boundsLock) {
            cardBounds.clear();
        }
        fullyRevealed = new boolean[bases.size()];
        setSfxVolumePercent(config != null ? config.sfxVolume() : 100);
        eventBus.post(new ChoicesPresentedEvent());
    }

    /**
     * Immediately dismisses the current presentation, clearing all transient state,
     * and invokes {@link #onDismiss} if set. Safe to call even if not active.
     */
    public void dismiss() {
        active = false;
        choices = null;
        presentedAt = null;
        minimized = false;
        hoveredIndex = lastHoverIndex = -1;
        hoverMinimize = hoverRestore = false;
        minimizeBounds = restoreBounds = null;
        animating = false;
        selectedIndex = -1;
        animStart = null;
        pickSent = false;
        anim.resetAll();
        popupPlayed.clear();

        synchronized (boundsLock) {
            cardBounds.clear();
        }
        fullyRevealed = new boolean[0];
        useGoldBgThisPresentation = false;
        if (onDismiss != null) try {
            onDismiss.run();
        } catch (Exception ignored) {
        }
    }

    /**
     * Main paint entry for the overlay. Draws title, cards, controls, and selection animation.
     * The method returns the final painted area to help RuneLite place subsequent overlays.
     *
     * @param g the graphics context provided by RuneLite.
     * @return a {@link Dimension} of the rendered bounds, or {@code null} if nothing is drawn.
     */
    @Override
    public Dimension render(Graphics2D g) {
        final List<String> local = choices;
        if (!active || local == null || local.isEmpty()) return null;

        renderer.enableAA(g);

        int availW = Math.max(1, client.getViewportWidth());
        int availH = Math.max(1, client.getViewportHeight());
        if (minimized) return renderer.drawRestorePill(g, availW, ROOT_Y, RESTORE_W, RESTORE_H,
                pendingCount, b -> restoreBounds = b, this::getAccent, hoverRestore);

        // Title
        int rowY = renderer.drawTitle(g, titleImg, availW, TITLE_TOP_Y, TITLE_GAP_Y, CARDS_PULL_UP_Y);

        // Reveal layout
        long ms = Duration.between(presentedAt, Instant.now()).toMillis();
        final int revealMs = (config != null ? Math.max(120, config.choiceRevealMs()) : POP_REVEAL_MS);

        final int sidePadding = 8;
        int maxCols = Math.max(1, (availW - (sidePadding * 2)) / (CARD_W + CARD_GAP));
        int cols = Math.max(1, Math.min(maxCols, local.size()));
        int rows = (local.size() + cols - 1) / cols;

        boolean[] revealSnapshot = new boolean[local.size()];
        List<Rectangle> newBounds = new ArrayList<>(local.size());

        for (int i = 0; i < local.size(); i++) {
            int row = i / cols;
            int startIndexOfRow = row * cols;
            int colsInThisRow = Math.min(cols, local.size() - startIndexOfRow);
            int colInRow = i - startIndexOfRow;

            int rowWidthThis = (CARD_W * colsInThisRow) + (CARD_GAP * Math.max(0, colsInThisRow - 1));
            int rowXThis = Math.max(sidePadding, (availW - rowWidthThis) / 2);

            int baseY = rowY + row * (CARD_H + CARD_GAP);
            int liftedY = baseY - (row * LIFT_PER_ROW);

            int x = rowXThis + colInRow * (CARD_W + CARD_GAP);
            int y = liftedY;

            long delay = (long) (i * revealMs * 0.6);
            float tReveal = PickAnimationEngine.clamp01((ms - delay) / (float) revealMs);
            boolean fully = tReveal >= 1.0f;
            revealSnapshot[i] = fully;

            if (tReveal <= 0f) {
                newBounds.add(null);
                continue;
            }
            if (!animating && popupPlayed.add(i)) anim.playPopup();

            double ease = PickAnimationEngine.cubicOut(tReveal);
            int slide = (int) ((1.0 - ease) * 24);
            newBounds.add(new Rectangle(x, y + slide, CARD_W, CARD_H));
        }

        fullyRevealed = revealSnapshot;
        synchronized (boundsLock) {
            cardBounds.clear();
            cardBounds.addAll(newBounds);
        }

        if (animating && !anim.particlesSeeded()) {
            anim.seedParticles(newBounds, selectedIndex);
        }

        long animElapsed = animating ? Duration.between(animStart, Instant.now()).toMillis() : 0;
        float explodeT = animating ? PickAnimationEngine.clamp01(animElapsed / (float) EXPLODE_MS) : 0f;

        // Non-selected cards
        for (int i = 0; i < local.size(); i++) {
            if (i == selectedIndex) continue;
            Rectangle card = newBounds.get(i);
            if (card == null && !animating) continue;

            long delay = (long) (i * revealMs * 0.6);
            float tReveal = PickAnimationEngine.clamp01((ms - delay) / (float) revealMs);
            if (!animating) {
                float easeReveal = (float) PickAnimationEngine.cubicOut(tReveal);
                float alpha = easeReveal, scale = 0.92f + 0.08f * easeReveal;
                boolean hovered = (i == hoveredIndex);
                renderer.drawCard(g, card, local.get(i), hovered, alpha, scale,
                        0f, false, useGoldBgThisPresentation ? cardBgGold : cardBgDefault,
                        itemManager, repo, this::getAccent);
                continue;
            }
            float scale = 1.0f - 0.4f * explodeT;
            float alpha = 1.0f - explodeT;
            if (alpha > 0.02f && card != null) {
                renderer.drawCard(g, card, local.get(i), false, alpha, scale,
                        0f, false, useGoldBgThisPresentation ? cardBgGold : cardBgDefault,
                        itemManager, repo, this::getAccent);
            }
            anim.drawParticles(g, i, explodeT, EXPLODE_MS);
        }

        // Selected card path
        if (selectedIndex >= 0 && selectedIndex < local.size()) {
            Rectangle startCard = newBounds.get(selectedIndex);
            if (startCard != null) {
                int targetX = (availW - CARD_W) / 2, targetY = (availH - CARD_H) / 2;
                long afterExplode = Math.max(0, animElapsed - EXPLODE_MS);
                float moveT = PickAnimationEngine.clamp01(afterExplode / (float) SEL_MOVE_MS);
                float fadeT = PickAnimationEngine.clamp01((afterExplode - SEL_MOVE_MS - SEL_HOLD_MS) / (float) SEL_FADE_MS);
                float easeMove = (float) PickAnimationEngine.cubicOut(moveT);

                int curX = Math.round(PickAnimationEngine.lerp(startCard.x, targetX, easeMove));
                int curY = Math.round(PickAnimationEngine.lerp(startCard.y, targetY, easeMove));
                float alpha = (fadeT <= 0f) ? 1f : (1f - fadeT);
                float scale = 1.0f + 0.08f * easeMove;
                float glowIn = Math.max(0f, easeMove);

                Rectangle lifted = new Rectangle(curX, curY, CARD_W, CARD_H);
                renderer.drawCard(g, lifted, local.get(selectedIndex), false, alpha, scale,
                        glowIn, true, useGoldBgThisPresentation ? cardBgGold : cardBgDefault,
                        itemManager, repo, this::getAccent);
            }
        }

        // Finish animation
        if (animating && animElapsed >= ANIM_TOTAL) {
            if (!pickSent && onPick != null && selectedIndex >= 0 && selectedIndex < local.size()) {
                pickSent = true;
                try {
                    onPick.accept(local.get(selectedIndex));
                } catch (Exception ignored) {
                }
            }
            dismiss();
            return new Dimension(availW, ROOT_Y + 24 + TITLE_GAP_Y + CARD_H + 16);
        }

        // minimize pill
        int contentHeight = rows * CARD_H + (rows - 1) * CARD_GAP - Math.max(0, rows - 1) * LIFT_PER_ROW;
        int totalW = availW, totalH = rowY + contentHeight + 16;

        final int pillX = 8;
        final int pillY = TITLE_TOP_Y + 15;
        minimizeBounds = renderer.drawMinimizePillAt(
                g, pillX, pillY, MIN_BTN_W, MIN_BTN_H,
                "Minimize", !animating && hoverMinimize, this::getAccent);

        return new Dimension(totalW, totalH);
    }

    /**
     * @param idx card index
     * @return true when a card has fully completed its reveal animation and is eligible for hover/select.
     */
    private boolean isCardFullyRevealed(int idx) {
        boolean[] arr = fullyRevealed;
        return idx >= 0 && arr != null && idx < arr.length && arr[idx];
    }

    /**
     * Hit test helper for card rectangles in overlay-local space.
     *
     * @param p overlay-local point
     * @return the index of the card under the point, or -1 if none.
     */
    private int indexAt(Point p) {
        List<Rectangle> snapshot;
        synchronized (boundsLock) {
            if (cardBounds.isEmpty()) return -1;
            snapshot = new ArrayList<>(cardBounds);
        }
        for (int i = 0; i < snapshot.size(); i++) {
            Rectangle r = snapshot.get(i);
            if (r != null && r.contains(p)) return i;
        }
        return -1;
    }

    /**
     * Resolve the accent color for UI elements. Falls back to a warm yellow when config is missing.
     *
     * @return non-null ARGB color used for pills, glows, and accents.
     */
    private Color getAccent() {
        return (config != null && config.accentColor() != null)
                ? config.accentColor() : new Color(255, 204, 0, 255);
    }
}

package com.choiceman.ui;

import com.choiceman.data.ChoiceManUnlocks;
import com.choiceman.data.ItemsRepository;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.*;
import java.awt.*;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Choice Man side panel UI.
 * Shows a searchable list of item bases from unlocked/obtained state.
 */
public class ChoiceManPanel extends PluginPanel {
    private static final ImageIcon NO_ICON = new ImageIcon(new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB));

    private static final Color PANEL_BG = new Color(37, 37, 37);
    private static final Color ROW_BG = new Color(60, 63, 65);
    private static final Color ROW_SELECTED_BG = new Color(75, 78, 80);
    private static final Color TEXT_DEFAULT = new Color(220, 220, 220);
    private static final Color BORDER_COLOR = new Color(80, 80, 80);
    private static final Color SEARCH_BG = new Color(30, 30, 30);
    private static final Color SEARCH_FIELD_BG = new Color(45, 45, 45);
    private static final Map<ListMode, String> MODE_TOOLTIPS = Map.of(
            ListMode.UNLOCKED, "Item bases you have unlocked.",
            ListMode.OBTAINED, "Item bases you have obtained.",
            ListMode.UNLOCKED_NOT_OBTAINED, "Item bases you have unlocked, but have not obtained yet.",
            ListMode.UNLOCKED_AND_OBTAINED, "Item bases that are both unlocked and obtained."
    );
    private final ItemsRepository repo;
    private final ChoiceManUnlocks unlocks;
    private final ItemManager itemManager;
    private final Map<String, ImageIcon> iconCache = new ConcurrentHashMap<>();
    private final Map<String, Integer> repIdCache = new ConcurrentHashMap<>();
    private final JLabel modeLabel = new JLabel("Unlocked Items");
    private final JTextField searchField = new JTextField();
    private final DefaultListModel<String> listModel = new DefaultListModel<>();
    private final JList<String> baseList = new JList<>(listModel);
    private final JLabel countLabel = new JLabel("0/0");
    private final JComboBox<ListMode> modeDropdown = new JComboBox<>(ListMode.values());
    private volatile ListMode listMode = ListMode.UNLOCKED;
    private volatile String searchText = "";

    public ChoiceManPanel(ItemsRepository repo, ChoiceManUnlocks unlocks, ItemManager itemManager) {
        this.repo = repo;
        this.unlocks = unlocks;
        this.itemManager = itemManager;
        init();
    }

    private void init() {
        setLayout(new BorderLayout());
        setBorder(new EmptyBorder(12, 12, 12, 12));
        setBackground(PANEL_BG);

        add(buildTop(), BorderLayout.NORTH);
        add(buildCenter(), BorderLayout.CENTER);
        add(buildBottom(), BorderLayout.SOUTH);

        baseList.setFixedCellHeight(36);
        baseList.setVisibleRowCount(-1);
        baseList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        baseList.setCellRenderer(new BaseCellRenderer());

        setMode(ListMode.UNLOCKED);
        updatePanel();
    }

    private JPanel buildTop() {
        JPanel top = new JPanel();
        top.setOpaque(false);
        top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));

        top.add(buildHeaderRow());
        top.add(Box.createVerticalStrut(10));
        top.add(buildDropdownRow());
        top.add(Box.createVerticalStrut(8));
        top.add(buildModeLabelRow());
        top.add(Box.createVerticalStrut(10));
        top.add(buildSearchBar());

        return top;
    }

    private JPanel buildHeaderRow() {
        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setOpaque(false);

        JLabel iconLabel = new JLabel();
        try {
            java.net.URL iconUrl = getClass().getResource("/net/runelite/client/plugins/choiceman/icon.png");
            if (iconUrl != null) {
                iconLabel.setIcon(new ImageIcon(iconUrl));
            }
        } catch (Exception ignored) {
        }

        JLabel titleLabel = new JLabel("Choice Man", SwingConstants.CENTER);
        titleLabel.setFont(new Font("SansSerif", Font.BOLD, 18));
        titleLabel.setForeground(TEXT_DEFAULT);

        headerPanel.add(iconLabel, BorderLayout.WEST);
        headerPanel.add(titleLabel, BorderLayout.CENTER);

        return headerPanel;
    }

    private JPanel buildDropdownRow() {
        JPanel row = new JPanel(new BorderLayout());
        row.setOpaque(false);

        modeDropdown.setFocusable(false);
        modeDropdown.setBackground(ROW_BG);
        modeDropdown.setForeground(Color.WHITE);
        modeDropdown.setFont(new Font("SansSerif", Font.BOLD, 12));
        modeDropdown.setBorder(new CompoundBorder(
                new LineBorder(BORDER_COLOR),
                new EmptyBorder(2, 6, 2, 6))
        );

        modeDropdown.setRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(
                    JList<?> list,
                    Object value,
                    int index,
                    boolean isSelected,
                    boolean cellHasFocus) {
                JLabel label = (JLabel) super.getListCellRendererComponent(
                        list, value, index, isSelected, cellHasFocus);

                label.setBorder(new EmptyBorder(4, 6, 4, 6));

                if (value instanceof ListMode) {
                    ListMode mode = (ListMode) value;
                    label.setText(index == -1 ? "Filter: " + mode.label() : mode.label());

                    String tooltip = MODE_TOOLTIPS.get(mode);
                    label.setToolTipText(tooltip);
                    modeDropdown.setToolTipText(tooltip);
                } else {
                    label.setToolTipText(null);
                }

                label.setBackground(isSelected ? ROW_SELECTED_BG : ROW_BG);
                label.setForeground(Color.WHITE);

                return label;
            }
        });

        modeDropdown.addActionListener(e ->
        {
            Object selected = modeDropdown.getSelectedItem();
            if (selected instanceof ListMode) {
                setMode((ListMode) selected);
                updatePanel();
            }
        });

        row.add(modeDropdown, BorderLayout.CENTER);
        return row;
    }

    private JPanel buildModeLabelRow() {
        JPanel row = new JPanel(new BorderLayout());
        row.setOpaque(false);

        modeLabel.setFont(new Font("SansSerif", Font.BOLD, 12));
        modeLabel.setForeground(new Color(210, 210, 210));

        row.add(modeLabel, BorderLayout.WEST);
        return row;
    }

    private JPanel buildSearchBar() {
        JPanel container = new JPanel(new BorderLayout());
        container.setOpaque(false);

        JPanel searchBox = new JPanel(new BorderLayout());
        searchBox.setBackground(SEARCH_BG);
        searchBox.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));

        JLabel icon = new JLabel("\uD83D\uDD0D");
        icon.setForeground(new Color(200, 200, 200));
        icon.setBorder(new EmptyBorder(0, 0, 0, 6));
        searchBox.add(icon, BorderLayout.WEST);

        searchField.setBackground(SEARCH_FIELD_BG);
        searchField.setForeground(Color.WHITE);
        searchField.setBorder(null);
        searchField.setCaretColor(Color.WHITE);

        searchField.addKeyListener(new KeyAdapter() {
            @Override
            public void keyReleased(KeyEvent e) {
                searchText = searchField.getText().toLowerCase(Locale.ROOT);
                updatePanel();
            }
        });

        searchBox.add(searchField, BorderLayout.CENTER);

        JButton clearButton = new JButton("x");
        clearButton.setFocusable(false);
        clearButton.setBorder(null);
        clearButton.setOpaque(false);
        clearButton.setContentAreaFilled(false);
        clearButton.setForeground(new Color(220, 80, 80));
        clearButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        clearButton.setToolTipText("Clear search");
        clearButton.addActionListener(e ->
        {
            searchField.setText("");
            searchText = "";
            updatePanel();
        });

        searchBox.add(clearButton, BorderLayout.EAST);

        container.add(searchBox, BorderLayout.CENTER);
        return container;
    }

    private JPanel buildCenter() {
        JScrollPane scroll = new JScrollPane(
                baseList,
                JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
                JScrollPane.HORIZONTAL_SCROLLBAR_NEVER
        );
        scroll.setBorder(null);

        JPanel wrap = new JPanel(new BorderLayout());
        wrap.setOpaque(false);
        wrap.setBorder(new CompoundBorder(
                new LineBorder(BORDER_COLOR),
                new EmptyBorder(6, 6, 6, 6))
        );

        wrap.add(scroll, BorderLayout.CENTER);
        return wrap;
    }

    private JPanel buildBottom() {
        JPanel bottom = new JPanel();
        bottom.setOpaque(false);
        bottom.setLayout(new BoxLayout(bottom, BoxLayout.Y_AXIS));

        bottom.add(Box.createVerticalStrut(10));

        JPanel countPanel = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
        countPanel.setOpaque(false);

        countLabel.setFont(new Font("Arial", Font.BOLD, 11));
        countLabel.setForeground(TEXT_DEFAULT);

        countPanel.add(countLabel);
        bottom.add(countPanel);
        bottom.add(Box.createVerticalStrut(4));

        return bottom;
    }

    private void setMode(ListMode mode) {
        listMode = mode;

        String tooltip = MODE_TOOLTIPS.get(mode);
        modeDropdown.setToolTipText(tooltip);

        switch (mode) {
            case UNLOCKED:
                modeLabel.setText("Unlocked Items");
                break;

            case OBTAINED:
                modeLabel.setText("Obtained Items");
                break;

            case UNLOCKED_NOT_OBTAINED:
                modeLabel.setText("Unlocked, not Obtained");
                break;

            case UNLOCKED_AND_OBTAINED:
                modeLabel.setText("Unlocked and Obtained");
                break;
        }
    }

    /**
     * External hook from the plugin to refresh the list after state changes.
     */
    public void refresh(ChoiceManUnlocks u) {
        updatePanel();
    }

    /**
     * Builds filtered snapshots, then applies model updates on the EDT.
     */
    public void updatePanel() {
        final ListMode modeSnapshot = listMode;
        final String searchSnapshot = searchText;

        List<String> unlocked = new ArrayList<>(unlocks.unlockedList());
        List<String> obtained = new ArrayList<>(unlocks.obtainedList());

        Set<String> unlockedSet = new HashSet<>(unlocked);
        Set<String> obtainedSet = new HashSet<>(obtained);

        List<String> base = new ArrayList<>();

        switch (modeSnapshot) {
            case UNLOCKED:
                base.addAll(unlocked);
                break;

            case OBTAINED:
                base.addAll(obtained);
                break;

            case UNLOCKED_NOT_OBTAINED:
                base.addAll(unlocked);
                base.removeIf(obtainedSet::contains);
                break;

            case UNLOCKED_AND_OBTAINED:
                base.addAll(unlocked);
                base.removeIf(s -> !obtainedSet.contains(s));
                break;
        }

        if (searchSnapshot != null && !searchSnapshot.isEmpty()) {
            base.removeIf(s -> !s.toLowerCase(Locale.ROOT).contains(searchSnapshot));
        }

        base.sort(String::compareToIgnoreCase);

        int totalBases = repo.getAllBases().size();

        SwingUtilities.invokeLater(() ->
        {
            listModel.clear();

            for (String s : base) {
                listModel.addElement(s);
            }

            countLabel.setText(base.size() + "/" + totalBases);

            baseList.revalidate();
            baseList.repaint();
        });
    }

    /**
     * Returns a cached representative icon for a base using the smallest item id.
     * Caches misses with a sentinel to avoid repeated lookups.
     */
    private ImageIcon getBaseIcon(String base) {
        ImageIcon cached = iconCache.get(base);
        if (cached != null) {
            return cached == NO_ICON ? null : cached;
        }

        Set<Integer> ids = repo.getIdsForBase(base);
        if (ids == null || ids.isEmpty()) {
            iconCache.put(base, NO_ICON);
            return null;
        }

        int representativeId = repIdCache.computeIfAbsent(base, b -> ids.stream().min(Integer::compareTo).orElse(0));
        if (representativeId <= 0) {
            iconCache.put(base, NO_ICON);
            return null;
        }

        BufferedImage img = itemManager.getImage(representativeId, 1, false);
        if (img == null) {
            iconCache.put(base, NO_ICON);
            return null;
        }

        ImageIcon icon = new ImageIcon(img);
        iconCache.put(base, icon);
        return icon;
    }

    @Override
    public Dimension getPreferredSize() {
        Dimension d = super.getPreferredSize();
        int viewportHeight = getViewportHeight();

        if (viewportHeight > 0 && d.height < viewportHeight) {
            return new Dimension(d.width, viewportHeight);
        }

        return d;
    }

    private int getViewportHeight() {
        Container parent = getParent();

        while (parent != null && !(parent instanceof JViewport)) {
            parent = parent.getParent();
        }

        if (parent != null) {
            return Math.max(((JViewport) parent).getHeight(), 0);
        }

        return 0;
    }

    private enum ListMode {
        UNLOCKED("Unlocked"),
        OBTAINED("Obtained"),
        UNLOCKED_NOT_OBTAINED("Unlocked, not Obtained"),
        UNLOCKED_AND_OBTAINED("Unlocked and Obtained");

        private final String label;

        ListMode(String label) {
            this.label = label;
        }

        public String label() {
            return label;
        }

        @Override
        public String toString() {
            return label;
        }
    }

    private class BaseCellRenderer extends JPanel implements ListCellRenderer<String> {
        private final JLabel iconLabel = new JLabel();
        private final JLabel nameLabel = new JLabel();

        BaseCellRenderer() {
            setLayout(new BorderLayout(8, 0));
            setOpaque(true);

            iconLabel.setPreferredSize(new Dimension(32, 32));

            add(iconLabel, BorderLayout.WEST);
            add(nameLabel, BorderLayout.CENTER);

            nameLabel.setFont(new Font("SansSerif", Font.PLAIN, 11));
        }

        @Override
        public Component getListCellRendererComponent(
                JList<? extends String> list,
                String base,
                int index,
                boolean isSelected,
                boolean cellHasFocus) {
            iconLabel.setIcon(getBaseIcon(base));
            iconLabel.setToolTipText(base);

            nameLabel.setText(base);
            nameLabel.setToolTipText(base);

            setToolTipText(base);
            setBackground(isSelected ? ROW_SELECTED_BG : ROW_BG);
            nameLabel.setForeground(TEXT_DEFAULT);

            return this;
        }
    }
}

package com.choiceman.ui;

import com.choiceman.data.ChoiceManUnlocks;
import com.choiceman.data.ItemsRepository;
import com.choiceman.filters.EnsouledHeadMapping;
import com.choiceman.menus.EnabledUI;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;

/**
 * Dims tracked item icon widgets whose Choice Man base is not usable.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ItemDimmerController
{
    private final Client client;
    private final ChoiceManUnlocks unlocks;
    private final ItemsRepository itemsRepo;
    private final ItemManager itemManager;

    private final Map<Integer, Boolean> dimDecisionCache = new HashMap<>(256);

    private volatile int dimOpacity = 150;

    @Setter
    private volatile boolean enabled = true;

    public void setDimOpacity(int opacity)
    {
        this.dimOpacity = Math.max(0, Math.min(255, opacity));
    }

    private boolean isCollectionLogWidget(Widget widget)
    {
        return widget != null && (widget.getId() >>> 16) == 621;
    }

    @Subscribe
    public void onBeforeRender(BeforeRender event)
    {
        if (!enabled || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        dimDecisionCache.clear();

        Widget[] roots = client.getWidgetRoots();
        if (roots == null)
        {
            return;
        }

        for (Widget root : roots)
        {
            if (root != null)
            {
                walkAndDim(root);
            }
        }
    }

    private void walkAndDim(Widget widget)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }

        int groupId = widget.getId() >>> 16;
        EnabledUI ui = EnabledUI.fromGroupId(groupId);
        if (ui != null && !ui.isGreyLockedItems())
        {
            walkChildren(widget);
            return;
        }

        if (isCollectionLogWidget(widget))
        {
            return;
        }

        int itemId = widget.getItemId();
        if (itemId > 0 && !isBankPlaceholderWidget(widget))
        {
            int targetOpacity = shouldDimMemoized(itemId) ? dimOpacity : 0;
            if (widget.getOpacity() != targetOpacity)
            {
                widget.setOpacity(targetOpacity);
            }
        }

        walkChildren(widget);
    }

    private void walkChildren(Widget widget)
    {
        Widget[] dynamicChildren = widget.getDynamicChildren();
        if (dynamicChildren != null)
        {
            for (Widget child : dynamicChildren)
            {
                walkAndDim(child);
            }
        }

        Widget[] staticChildren = widget.getStaticChildren();
        if (staticChildren != null)
        {
            for (Widget child : staticChildren)
            {
                walkAndDim(child);
            }
        }

        Widget[] nestedChildren = widget.getNestedChildren();
        if (nestedChildren != null)
        {
            for (Widget child : nestedChildren)
            {
                walkAndDim(child);
            }
        }
    }

    private boolean shouldDimMemoized(int rawItemId)
    {
        int canonical;
        try
        {
            int mapped = EnsouledHeadMapping.toTradeableId(rawItemId);
            canonical = itemManager.canonicalize(mapped);
        }
        catch (Exception ignored)
        {
            return false;
        }

        if (canonical <= 0)
        {
            return false;
        }

        Boolean cached = dimDecisionCache.get(canonical);
        if (cached != null)
        {
            return cached;
        }

        boolean result = shouldDimCanonical(canonical);
        dimDecisionCache.put(canonical, result);
        return result;
    }

    private boolean shouldDimCanonical(int canonicalItemId)
    {
        try
        {
            String base = itemsRepo.getBaseForId(canonicalItemId);
            if (base == null)
            {
                return false;
            }

            return !unlocks.isBaseUsable(base);
        }
        catch (Exception ignored)
        {
            return false;
        }
    }

    private boolean isBankPlaceholderWidget(Widget widget)
    {
        return widget != null && widget.getItemId() > 0 && widget.getItemQuantity() == 0;
    }
}

package com.choiceman.ui;

import net.runelite.api.Client;
import net.runelite.api.SpritePixels;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Creates and caches scaled item sprites for use in the unlocks view.
 * <p>
 * Notes on threading
 * • ItemManager#getImage may return an AsyncBufferedImage when off the game thread; the image will fill in later, which is fine for UI usage. :contentReference[oaicite:0]{index=0}
 * • Writes to Client#getSpriteOverrides and clearing the widget sprite cache must happen on the client thread. :contentReference[oaicite:1]{index=1}
 * • ImageUtil helpers are pure image operations and are safe to call off-thread. :contentReference[oaicite:2]{index=2}
 */
@Singleton
public final class ItemSpriteCache {
    private static final int ICON_SIZE = 32;
    private static final int FIRST_CUSTOM_SPRITE_ID = 0x10000;

    private final ItemManager itemManager;
    private final Client client;
    private final ClientThread clientThread;

    /**
     * itemId -> generated spriteId
     */
    private final Map<Integer, Integer> spriteIds = new ConcurrentHashMap<>();

    /**
     * Unique sprite IDs for overrides.
     */
    private final AtomicInteger nextSpriteId = new AtomicInteger(FIRST_CUSTOM_SPRITE_ID);

    @Inject
    public ItemSpriteCache(ItemManager itemManager, Client client, ClientThread clientThread) {
        this.itemManager = itemManager;
        this.client = client;
        this.clientThread = clientThread;
    }

    /**
     * Returns a sprite ID for the given item.
     * If missing, generates a 32x32 override image and registers it on the client thread.
     *
     * @param itemId any item definition ID
     * @return the override sprite ID, or -1 if the base item image is unavailable
     */
    public int getSpriteId(int itemId) {
        // Fast path if we already have it
        Integer cached = spriteIds.get(itemId);
        if (cached != null) {
            return cached;
        }

        // Obtain the base item image; may be an AsyncBufferedImage that fills later
        BufferedImage img = itemManager.getImage(itemId, 1, false);
        if (img == null) {
            return -1;
        }

        // Resize off-thread
        BufferedImage resized = ImageUtil.resizeImage(img, ICON_SIZE, ICON_SIZE);

        // Build SpritePixels and register the override on the client thread
        final int spriteId = nextSpriteId.getAndIncrement();
        clientThread.invokeLater(() ->
        {
            SpritePixels pixels = ImageUtil.getImageSpritePixels(resized, client);
            client.getSpriteOverrides().put(spriteId, pixels);
        });

        // Publish to cache after scheduling registration
        spriteIds.put(itemId, spriteId);
        return spriteId;
    }

    /**
     * Removes all generated overrides and resets the ID counter.
     * Must run on the client thread to safely mutate the override map and cache.
     */
    public void clear() {
        Map<Integer, Integer> snapshot = Map.copyOf(spriteIds);
        spriteIds.clear();

        clientThread.invokeLater(() ->
        {
            snapshot.values().forEach(id -> client.getSpriteOverrides().remove(id));
            nextSpriteId.set(FIRST_CUSTOM_SPRITE_ID);
        });
    }
}

package com.choiceman.ui;

import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Adds a small button to the Music tab that opens the Choice Man unlocks view.
 */
@Singleton
public class MusicOpenButton {
    private static final int MUSIC_GROUP = InterfaceID.Music.UNIVERSE >>> 16;

    private static final int SPRITE_OPEN = 1976;
    private static final int W = 14, H = 14;

    private static final int GAP = 4;
    private static final int NUDGE_LEFT = 30;
    private static final int NUDGE_DOWN = 0;

    private final Client client;
    private final ClientThread clientThread;
    private final UnlocksWidgetController unlocksWidgetController;

    private Widget icon;
    @Getter
    private volatile boolean overrideActive = false;

    private int lastX = Integer.MIN_VALUE;
    private int lastY = Integer.MIN_VALUE;

    @Inject
    public MusicOpenButton(Client client, ClientThread clientThread, UnlocksWidgetController unlocksWidgetController) {
        this.client = client;
        this.clientThread = clientThread;
        this.unlocksWidgetController = unlocksWidgetController;
    }

    private static void move(Widget w, int x, int y, int width, int height) {
        w.setOriginalX(x);
        w.setOriginalY(y);
        w.setOriginalWidth(width);
        w.setOriginalHeight(height);
        w.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
        w.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
    }

    private static Widget[] merge(Widget[] a, Widget[] b) {
        if (a == null) return b;
        if (b == null) return a;
        Widget[] out = new Widget[a.length + b.length];
        System.arraycopy(a, 0, out, 0, a.length);
        System.arraycopy(b, 0, out, a.length, b.length);
        return out;
    }

    /**
     * Called from plugin start on the client thread.
     */
    public void onStart() {
        clientThread.invokeLater(this::placeIcon);
    }

    /**
     * Called from plugin stop on the client thread.
     */
    public void onStop() {
        clientThread.invokeLater(this::hide);
    }

    public void onOverrideActivated() {
        overrideActive = true;
        clientThread.invokeLater(this::hide);
    }

    public void onOverrideDeactivated() {
        overrideActive = false;
        clientThread.invokeLater(this::placeIcon);
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded e) {
        if (e.getGroupId() == MUSIC_GROUP) {
            clientThread.invokeLater(this::placeIcon);
        }
    }

    private void placeIcon() {
        if (overrideActive) {
            hide();
            return;
        }

        Widget contents = client.getWidget(InterfaceID.Music.CONTENTS);
        Widget frame = client.getWidget(InterfaceID.Music.FRAME);
        if (contents == null || frame == null) {
            hide();
            return;
        }

        // If the current icon was orphaned by a UI rebuild, recreate it.
        if (icon != null && icon.getParent() != contents) {
            icon = null;
            lastX = Integer.MIN_VALUE;
            lastY = Integer.MIN_VALUE;
        }

        Widget root = client.getWidget(InterfaceID.Music.UNIVERSE);
        Widget toggleAll = findByAction(root, "Toggle all");

        int x, y;
        if (toggleAll != null) {
            x = toggleAll.getOriginalX() - W - GAP - NUDGE_LEFT;
            y = toggleAll.getOriginalY() + (toggleAll.getOriginalHeight() - H) / 2 + NUDGE_DOWN;
        } else {
            int frameRight = frame.getOriginalX() + frame.getOriginalWidth();
            x = frameRight - W - (GAP + 10) - NUDGE_LEFT;
            y = Math.max(6, frame.getOriginalY() - H - GAP) + NUDGE_DOWN;
        }

        if (icon == null) {
            icon = contents.createChild(-1, WidgetType.GRAPHIC);
            icon.setHasListener(true);
            icon.setAction(0, "View unlocks");
            icon.setOnOpListener((JavaScriptCallback) ev -> unlocksWidgetController.overrideWithLatest());
            icon.setSpriteId(SPRITE_OPEN);
        }

        icon.setHidden(false);

        // Only move/revalidate if needed.
        if (x != lastX || y != lastY || icon.getOriginalWidth() != W || icon.getOriginalHeight() != H) {
            move(icon, x, y, W, H);
            icon.revalidate();
            lastX = x;
            lastY = y;
        }
    }

    private void hide() {
        if (icon != null) {
            icon.setHidden(true);
            // keep placement cache; UI rebuild will reset it when icon parent changes
        }
    }

    /**
     * Depth-first search for a descendant that exposes the given right-click action text.
     */
    private Widget findByAction(Widget parent, String action) {
        if (parent == null) return null;
        Widget[] kids = merge(parent.getChildren(), parent.getDynamicChildren());
        if (kids == null) return null;

        for (Widget c : kids) {
            if (c == null) continue;

            String[] actions = c.getActions();
            if (actions != null) {
                for (String a : actions) {
                    if (a != null && a.equalsIgnoreCase(action)) {
                        return c;
                    }
                }
            }

            Widget deeper = findByAction(c, action);
            if (deeper != null) return deeper;
        }
        return null;
    }
}

package com.choiceman.ui;

import net.runelite.client.audio.AudioPlayer;

import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ThreadLocalRandom;

/**
 * Drives the pick animation sequence for Choice Man:
 * <ul>
 *   <li>Particle burst/explosion effect for non-selected cards</li>
 *   <li>Lightweight audio playback for hover/popup/select SFX through RuneLite's audio player</li>
 * </ul>
 * <p>
 * Stateless from the caller’s perspective; per-presentation state (particles and SFX volume)
 * is contained within the instance. Thread-safe for the typical render-thread + input-thread usage.
 */
final class PickAnimationEngine {
    private final Map<Integer, List<Particle>> particles = new ConcurrentHashMap<>();
    private final AudioPlayer audioPlayer;
    private volatile boolean particlesSeeded = false;
    private Sfx sfxHover, sfxPopup, sfxSelect;

    PickAnimationEngine(AudioPlayer audioPlayer) {
        this.audioPlayer = audioPlayer;
    }

    /**
     * Easing function (cubic-out) used by animations: starts fast, ends slow.
     *
     * @param t normalized time in [0, 1]
     * @return eased value in [0, 1]
     */
    static double cubicOut(double t) {
        double f = t - 1.0;
        return f * f * f + 1.0;
    }

    /**
     * Clamp a float value into the [0, 1] range.
     *
     * @param f value
     * @return clamped value
     */
    static float clamp01(float f) {
        return f < 0 ? 0 : (f > 1 ? 1 : f);
    }

    /**
     * Linear interpolation between two ints, returning a float.
     *
     * @param a start
     * @param b end
     * @param t normalized position [0, 1]
     * @return interpolated value
     */
    static float lerp(int a, int b, float t) {
        return (a + (b - a) * t);
    }

    /**
     * Registers three short WAV effects for playback through RuneLite's audio player.
     */
    void loadSfx() {
        try {
            sfxHover = Sfx.load(audioPlayer, "/com/choiceman/sounds/CardMouseover.wav");
        } catch (Exception ignored) {
        }
        try {
            sfxPopup = Sfx.load(audioPlayer, "/com/choiceman/sounds/CardPopup.wav");
        } catch (Exception ignored) {
        }
        try {
            sfxSelect = Sfx.load(audioPlayer, "/com/choiceman/sounds/CardSelection.wav");
        } catch (Exception ignored) {
        }
    }

    /**
     * Set the global volume for all SFX (0–100).
     *
     * @param p percentage (0 = muted, 100 = full)
     */
    void setVolumePercent(int p) {
        float v = clamp01(p / 100f);
        if (sfxHover != null) sfxHover.setVolume(v);
        if (sfxPopup != null) sfxPopup.setVolume(v);
        if (sfxSelect != null) sfxSelect.setVolume(v);
    }

    /**
     * Play the hover SFX if available.
     */
    void playHover() {
        if (sfxHover != null) sfxHover.play();
    }

    /**
     * Play the popup SFX if available.
     */
    void playPopup() {
        if (sfxPopup != null) sfxPopup.play();
    }

    /**
     * Play the select SFX if available.
     */
    void playSelect() {
        if (sfxSelect != null) sfxSelect.play();
    }

    /**
     * @return true when particle systems have been seeded for the current presentation.
     */
    boolean particlesSeeded() {
        return particlesSeeded;
    }

    /**
     * Clears all particle systems and marks them as not seeded.
     */
    void resetParticles() {
        particles.clear();
        particlesSeeded = false;
    }

    /**
     * Resets all internal per-run state (currently just particles).
     */
    void resetAll() {
        resetParticles();
    }

    /**
     * Seeds particle systems for each non-selected card. Call once right before the explosion
     * animation so that positions are based on the final layout.
     *
     * @param bounds list of card bounds in overlay space
     * @param selIdx selected card index; all others will emit particles
     */
    void seedParticles(List<Rectangle> bounds, int selIdx) {
        particles.clear();
        ThreadLocalRandom rnd = ThreadLocalRandom.current();
        for (int i = 0; i < bounds.size(); i++) {
            if (i == selIdx) continue;
            Rectangle r = bounds.get(i);
            if (r == null) continue;
            int cx = r.x + r.width / 2, cy = r.y + r.height / 2;
            int count = 26 + rnd.nextInt(12);
            List<Particle> list = new ArrayList<>(count);
            for (int p = 0; p < count; p++) {
                double angle = rnd.nextDouble(0, Math.PI * 2), speed = 90 + rnd.nextDouble(90);
                float vx = (float) (Math.cos(angle) * speed), vy = (float) (Math.sin(angle) * speed - 40);
                float size = 2.0f + rnd.nextFloat() * 2.2f;
                int rshift = rnd.nextInt(30), gshift = rnd.nextInt(20);
                Color c = new Color(255, 200 + gshift, 40 + rshift, 255);
                list.add(new Particle(cx, cy, vx, vy, size, c));
            }
            particles.put(i, list);
        }
        particlesSeeded = true;
    }

    /**
     * Draws and advances particles for a single non-selected card, given the explosion timeline.
     *
     * @param g           graphics context
     * @param cardIndex   index of the card whose particles to draw
     * @param explodeNorm normalized time within the explosion [0..1]
     * @param explodeMs   total explosion duration in milliseconds
     */
    void drawParticles(Graphics2D g, int cardIndex, float explodeNorm, int explodeMs) {
        List<Particle> list = particles.get(cardIndex);
        if (list == null || list.isEmpty()) return;

        float grav = 120f;
        Composite old = g.getComposite();
        float t = clamp01(explodeNorm);
        float seconds = explodeMs / 1000f;

        for (Particle p : list) {
            float x = p.x0 + p.vx * t * seconds;
            float y = p.y0 + (p.vy * t * seconds) + 0.5f * grav * t * t;
            int alpha = Math.max(0, Math.min(255, (int) (255 * (1.0f - t))));
            if (alpha <= 0) continue;

            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha / 255f));
            g.setColor(new Color(p.color.getRed(), p.color.getGreen(), p.color.getBlue(), alpha));

            float size = Math.max(0.5f, p.size * (1.0f - t));
            int s = Math.max(1, Math.round(size));
            g.fillOval(Math.round(x) - s / 2, Math.round(y) - s / 2, s, s);
        }
        g.setComposite(old);
    }

    /**
     * Immutable particle parameters for a single dot in the explosion effect.
     */
    private static final class Particle {
        final float x0, y0, vx, vy, size;
        final Color color;

        /**
         * @param x0    origin x-position
         * @param y0    origin y-position
         * @param vx    initial x-velocity (px/s scaled by timeline)
         * @param vy    initial y-velocity (px/s scaled by timeline)
         * @param size  initial diameter in pixels
         * @param color particle color (alpha is animated over time)
         */
        Particle(float x0, float y0, float vx, float vy, float size, Color color) {
            this.x0 = x0;
            this.y0 = y0;
            this.vx = vx;
            this.vy = vy;
            this.size = size;
            this.color = color;
        }
    }

    /**
     * Sound-effect helper that delegates playback to RuneLite's {@link AudioPlayer}.
     */
    private static final class Sfx {
        private final AudioPlayer audioPlayer;
        private final String resourcePath;
        private volatile float volumeLinear = 1f;

        private Sfx(AudioPlayer audioPlayer, String resourcePath) {
            this.audioPlayer = audioPlayer;
            this.resourcePath = resourcePath;
        }

        /**
         * Verifies a WAV resource exists and creates a playback wrapper for it.
         *
         * @param resourcePath classpath resource path to a small WAV file
         * @return Sfx instance
         * @throws Exception if the resource cannot be found
         */
        static Sfx load(AudioPlayer audioPlayer, String resourcePath) throws Exception {
            if (ChoiceManOverlay.class.getResource(resourcePath) == null) {
                throw new Exception("Missing SFX: " + resourcePath);
            }

            return new Sfx(audioPlayer, resourcePath);
        }

        /**
         * Sets the linear volume (0..1) used for this sound effect.
         *
         * @param v linear gain (0 mutes).
         */
        void setVolume(float v) {
            volumeLinear = v;
        }

        /**
         * Converts the current linear volume to a decibel gain value for RuneLite audio playback.
         */
        private float gainDb() {
            if (volumeLinear <= 0f) {
                return -80.0f;
            }

            return (float) (20.0 * Math.log10(volumeLinear));
        }

        /**
         * Plays one instance of the effect through RuneLite's audio player.
         */
        void play() {
            try {
                if (volumeLinear <= 0f) {
                    return;
                }

                audioPlayer.play(ChoiceManOverlay.class, resourcePath, gainDb());
            } catch (Exception ignored) {
            }
        }
    }
}

package com.choiceman.ui;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.game.SpriteOverride;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Temporarily replaces a widget sprite (the Music tab icon) while the Choice Man
 * unlocks view is active, and restores the original once deactivated.
 * <p>
 * All client state mutations (sprite registration and cache reset) are scheduled
 * on the client thread to avoid race conditions with the game loop.
 */
@Slf4j
@Singleton
public final class SpriteOverrideManager implements SpriteOverride {
    private static final int SPRITE_ID = 910;
    private static final String RESOURCE = "/com/choiceman/ui/unlocks.png";

    private final SpriteManager spriteManager;
    private final Client client;
    private final ClientThread clientThread;

    @Inject
    public SpriteOverrideManager(
            SpriteManager spriteManager,
            Client client,
            ClientThread clientThread
    ) {
        this.spriteManager = spriteManager;
        this.client = client;
        this.clientThread = clientThread;
    }

    public void register() {
        spriteManager.addSpriteOverrides(new SpriteOverride[]{this});
        clientThread.invokeLater(() -> {
            try (var in = SpriteOverrideManager.class.getResourceAsStream(RESOURCE)) {
                if (in != null) {
                    var img = javax.imageio.ImageIO.read(in);
                    if (img != null) {
                        var pixels = net.runelite.client.util.ImageUtil.getImageSpritePixels(img, client);
                        client.getSpriteOverrides().put(SPRITE_ID, pixels);
                    }
                } else {
                    log.debug("[ChoiceMan] unlocks.png not found at {}", RESOURCE);
                }
            } catch (Exception ignored) { /* noop */ }

            client.getWidgetSpriteCache().reset();
        });
    }

    public void unregister() {
        spriteManager.removeSpriteOverrides(new SpriteOverride[]{this});
        clientThread.invokeLater(() -> {
            client.getSpriteOverrides().remove(SPRITE_ID); // clear any direct override too
            client.getWidgetSpriteCache().reset();
        });
    }

    @Override
    public int getSpriteId() {
        return SPRITE_ID;
    }

    @Override
    public String getFileName() {
        return RESOURCE;
    }
}

package com.choiceman.ui;

import com.choiceman.ChoiceManConfig;

import net.runelite.api.Client;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Restores or preserves the Music tab’s UI state when the inventory tab selection changes.
 * When leaving the Music tab, it restores the override if active and shows top-row controls;
 * when entering the Music tab without the override, ensures top-row controls are visible.
 * <p>
 * All UI-mutating operations are posted to the client thread.
 */
@Singleton
public class TabListener {
    private static final int MUSIC_TAB = 13;
    private static final int VARC_INV_TAB = 171;

    private final Client client;
    private final ClientThread clientThread;
    private final UnlocksWidgetController widgetController;
    private final ChoiceManConfig config;

    @Inject
    public TabListener(Client client,
                       ClientThread clientThread,
                       UnlocksWidgetController widgetController,
                       ChoiceManConfig config) {
        this.client = client;
        this.clientThread = clientThread;
        this.widgetController = widgetController;
        this.config = config;
    }

    @Subscribe
    public void onVarClientIntChanged(VarClientIntChanged ev) {
        if (ev.getIndex() != VARC_INV_TAB) {
            return;
        }

        int newTab = client.getVarcIntValue(VARC_INV_TAB);

        if (newTab != MUSIC_TAB) {
            clientThread.invokeLater(() -> {
                if (widgetController.isOverrideActive()) {
                    if (!config.showUnlocksAlwaysOpen()) {
                        widgetController.restore();
                        widgetController.restoreTopRowControls();
                    }
                } else {
                    widgetController.restoreTopRowControls();
                }
            });
        } else {
            // Entering Music tab
            if (!widgetController.isOverrideActive()) {
                clientThread.invokeLater(widgetController::restoreTopRowControls);
            }
        }
    }
}

package com.choiceman.ui;

import net.runelite.client.eventbus.EventBus;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Wires up the small Music-tab entry point:
 * registers the button and the tab listener with the client event bus,
 * and ensures the button’s widget is placed/removed at the right times.
 * <p>
 * Idempotent lifecycle: repeated startUp/shutDown calls are safe.
 */
@Singleton
public final class UnlocksTabUI {
    private final EventBus eventBus;
    private final MusicOpenButton button;
    private final TabListener tabListener;

    // Guard against double-register or double-unregister in edge cases
    private final AtomicBoolean registered = new AtomicBoolean(false);

    @Inject
    public UnlocksTabUI(EventBus eventBus, MusicOpenButton button, TabListener tabListener) {
        this.eventBus = eventBus;
        this.button = button;
        this.tabListener = tabListener;
    }

    /**
     * Registers listeners and shows the Music-tab icon.
     * Safe to call multiple times; no duplicate registrations will occur.
     */
    public void startUp() {
        if (!registered.compareAndSet(false, true)) {
            return;
        }

        eventBus.register(button);
        eventBus.register(tabListener);
        button.onStart();
    }

    /**
     * Unregisters listeners and hides the Music-tab icon.
     * Safe to call multiple times.
     */
    public void shutDown() {
        if (!registered.compareAndSet(true, false)) {
            return;
        }
        button.onStop();

        eventBus.unregister(tabListener);
        eventBus.unregister(button);
    }
}

package com.choiceman.ui;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Lightweight hover tooltip for the music-tab unlock grid.
 * Renders the base name when the mouse is inside an icon's widget bounds.
 * <p>
 * Notes:
 * - Runs in {@link Overlay#render(Graphics2D)} as a DYNAMIC overlay above widgets
 * - Uses {@link Widget#getBounds()} to test hitboxes against the canvas-space mouse position. :contentReference[oaicite:1]{index=1}
 */
@Singleton
public class UnlocksTooltipOverlay extends Overlay {
    private static final Color BG = new Color(0, 0, 0, 120);
    private static final Color BORDER = new Color(50, 50, 50, 220);
    private static final Color TEXT = Color.WHITE;

    private final Client client;
    private final UnlocksWidgetController controller;

    @Inject
    public UnlocksTooltipOverlay(Client client, UnlocksWidgetController controller) {
        this.client = client;
        this.controller = controller;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D g) {
        if (!controller.isOverrideActive()) {
            return null;
        }

        final Point mouse = client.getMouseCanvasPosition();
        if (mouse == null) {
            return null;
        }

        // Snapshot to avoid concurrent modification if the grid is rebuilt on the client thread
        final List<Map.Entry<Widget, String>> entries = new ArrayList<>(controller.getIconBaseMap().entrySet());

        for (Map.Entry<Widget, String> e : entries) {
            final Widget w = e.getKey();
            if (w == null || w.isHidden()) {
                continue;
            }

            final Rectangle bounds = w.getBounds();
            if (bounds == null) {
                continue;
            }

            if (bounds.contains(mouse.getX(), mouse.getY())) {
                drawTooltip(g, e.getValue(), mouse);
                break; // show one tooltip at a time
            }
        }

        return null;
    }

    private void drawTooltip(Graphics2D g, String text, Point mouse) {
        if (text == null || text.isEmpty()) {
            return;
        }

        final FontMetrics fm = g.getFontMetrics();
        final int pad = 4;

        final int w = fm.stringWidth(text) + pad * 2;
        final int h = fm.getHeight() + pad * 2;

        int x = mouse.getX() + 10;
        int y = mouse.getY() - 10 - h;

        final Rectangle clip = g.getClipBounds();
        if (clip != null) {
            x = Math.max(clip.x, Math.min(x, clip.x + clip.width - w));
            y = Math.max(clip.y, Math.min(y, clip.y + clip.height - h));
        }

        g.setColor(BG);
        g.fillRect(x, y, w, h);

        g.setColor(BORDER);
        g.drawRect(x, y, w, h);

        g.setColor(TEXT);
        g.drawString(text, x + pad, y + pad + fm.getAscent());
    }
}

package com.choiceman.ui;

import com.choiceman.data.ChoiceManUnlocks;
import com.choiceman.data.ItemsRepository;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.ScriptEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Replaces the Music tab content with a grid of Choice Man unlocks (one icon per base) and a progress bar,
 * then restores the original UI on demand. Provides a lightweight refresh path while active.
 */
@Singleton
public final class UnlocksWidgetController
{
    private static final int MUSIC_GROUP = InterfaceID.Music.UNIVERSE >>> 16;

    private static final int ICON_SIZE = 32;
    private static final int PADDING = 4;
    private static final int COLUMNS = 4;
    private static final int MARGIN_X = 8;
    private static final int MARGIN_Y = 8;

    private static final int CLOSE_SPRITE = 520;
    private static final int CLOSE_SIZE = 10;
    private static final int CLOSE_PAD = 4;

    private static final int BAR_HEIGHT = 15;

    private static final String CFG_GROUP = "choiceman";
    private static final String CFG_FAVS = "unlockFavorites";
    private static final int STAR_SPRITE = 366;   // yellow star

    // Widgets we hide during override and MUST ensure come back after restore.
    private static final int[] RESTORE_FORCE_VISIBLE_PACKEDS = new int[]
            {
                    InterfaceID.Music.CONTROLS,
                    InterfaceID.Music.AREA,
                    InterfaceID.Music.SHUFFLE,
                    InterfaceID.Music.SINGLE,
                    InterfaceID.Music.SKIP,
                    InterfaceID.Music.PLAYLIST,
                    InterfaceID.Music.DROPDOWN_CONTAINER,
                    InterfaceID.Music.DROPDOWN,
                    InterfaceID.Music.DROPDOWN_CONTENT,
                    InterfaceID.Music.DROPDOWN_SCROLLBAR,
                    InterfaceID.Music.COUNT,
                    InterfaceID.Music.NOW_PLAYING_TEXT,
            };

    private static final int[] RESTORE_FORCE_SHOW = new int[]
            {
                    InterfaceID.Music.CONTROLS,
                    InterfaceID.Music.AREA,
                    InterfaceID.Music.SHUFFLE,
                    InterfaceID.Music.SINGLE,
                    InterfaceID.Music.SKIP,
                    InterfaceID.Music.PLAYLIST,
                    InterfaceID.Music.DROPDOWN_CONTAINER,
                    InterfaceID.Music.DROPDOWN,
                    InterfaceID.Music.DROPDOWN_CONTENT,
                    InterfaceID.Music.DROPDOWN_SCROLLBAR,
                    InterfaceID.Music.COUNT,
                    InterfaceID.Music.NOW_PLAYING_TEXT,

                    InterfaceID.Music.JUKEBOX,
                    InterfaceID.Music.INNER,
                    InterfaceID.Music.SCROLLABLE,
                    InterfaceID.Music.SCROLLBAR,
                    InterfaceID.Music.NOW_PLAYING,
                    InterfaceID.Music.CONTENTS,
                    InterfaceID.Music.OVERLAY,
                    InterfaceID.Music.UNIVERSE
            };

    private final Client client;
    private final ClientThread clientThread;
    private final ChoiceManUnlocks unlocks;
    private final ItemsRepository itemsRepo;
    private final ItemSpriteCache itemSpriteCache;
    private final SpriteOverrideManager spriteOverrideManager;
    private final ConfigManager configManager;

    /**
     * Icon widget -> base name for hover tooltips.
     */
    @Getter
    private final Map<Widget, String> iconBaseMap = new LinkedHashMap<>();
    private final Set<String> favoriteBases = new LinkedHashSet<>();

    private final List<Widget> createdScrollWidgets = new ArrayList<>();
    private final List<Widget> createdRootWidgets = new ArrayList<>();
    @Getter
    private volatile boolean overrideActive = false;

    private String originalTitleText;
    private Widget pluginToggle;   // "View Unlocks"
    private boolean favoritesLoaded = false;

    private final Map<Integer, Boolean> hiddenStateByPacked = new HashMap<>();

    private static final class ChildBackup
    {
        List<Widget> stat = Collections.emptyList();
        List<Widget> dyn = Collections.emptyList();

        boolean captured()
        {
            return !stat.isEmpty() || !dyn.isEmpty();
        }
    }

    private enum SnapTarget
    {
        SCROLLABLE(InterfaceID.Music.SCROLLABLE),
        JUKEBOX(InterfaceID.Music.JUKEBOX),
        NOW_PLAYING(InterfaceID.Music.NOW_PLAYING),
        CONTROLS(InterfaceID.Music.CONTROLS);

        final int packed;

        SnapTarget(int packed)
        {
            this.packed = packed;
        }
    }

    private final EnumMap<SnapTarget, ChildBackup> backups = new EnumMap<>(SnapTarget.class);

    @Inject
    public UnlocksWidgetController(
            Client client,
            ClientThread clientThread,
            ChoiceManUnlocks unlocks,
            ItemsRepository itemsRepo,
            ItemSpriteCache itemSpriteCache,
            SpriteOverrideManager spriteOverrideManager,
            ConfigManager configManager
    )
    {
        this.client = client;
        this.clientThread = clientThread;
        this.unlocks = unlocks;
        this.itemsRepo = itemsRepo;
        this.itemSpriteCache = itemSpriteCache;
        this.spriteOverrideManager = spriteOverrideManager;
        this.configManager = configManager;
    }

    private Widget widget(int packed)
    {
        return client.getWidget(packed);
    }

    private void setHiddenRevalidate(Widget w, boolean hidden)
    {
        if (w == null)
        {
            return;
        }
        w.setHidden(hidden);
        w.revalidate();
    }

    private void revalidateScroll(Widget scrollbar)
    {
        if (scrollbar == null)
        {
            return;
        }
        scrollbar.revalidate();
        scrollbar.revalidateScroll();
    }

    private void rememberAndHidePacked(int packed)
    {
        Widget w = widget(packed);
        if (w == null)
        {
            return;
        }
        hiddenStateByPacked.putIfAbsent(packed, w.isHidden());
        setHiddenRevalidate(w, true);
    }

    private void rememberAndHideAll(int... packeds)
    {
        for (int p : packeds)
        {
            rememberAndHidePacked(p);
        }
    }

    private void restoreHiddenStates()
    {
        for (Map.Entry<Integer, Boolean> e : hiddenStateByPacked.entrySet())
        {
            Widget w = widget(e.getKey());
            if (w == null)
            {
                continue;
            }
            setHiddenRevalidate(w, Boolean.TRUE.equals(e.getValue()));
        }
        hiddenStateByPacked.clear();
    }

    private void forceShowCoreMusicControls()
    {
        for (int packed : RESTORE_FORCE_SHOW)
        {
            setHiddenRevalidate(widget(packed), false);
        }
    }

    private static List<Widget> copyChildren(Widget parent, boolean dynamic)
    {
        if (parent == null)
        {
            return Collections.emptyList();
        }
        Widget[] kids = dynamic ? parent.getDynamicChildren() : parent.getChildren();
        if (kids == null)
        {
            return Collections.emptyList();
        }
        List<Widget> out = new ArrayList<>(kids.length);
        for (Widget k : kids)
        {
            if (k != null) out.add(k);
        }
        return out;
    }

    private void ensureBaselineCaptured()
    {
        for (SnapTarget t : SnapTarget.values())
        {
            ChildBackup b = backups.computeIfAbsent(t, k -> new ChildBackup());
            if (b.captured())
            {
                continue;
            }
            Widget w = widget(t.packed);
            b.stat = copyChildren(w, false);
            b.dyn = copyChildren(w, true);
        }
    }

    private static void hideChildren(Widget[] kids)
    {
        if (kids == null)
        {
            return;
        }
        for (Widget w : kids)
        {
            if (w != null) w.setHidden(true);
        }
    }

    private static void unhideAndRevalidate(List<Widget> kids)
    {
        if (kids == null)
        {
            return;
        }
        for (Widget w : kids)
        {
            if (w != null && w.getType() != 0)
            {
                w.setHidden(false);
                w.revalidate();
            }
        }
    }

    private static void restoreChildren(Widget parent, List<Widget> staticKids, List<Widget> dynamicKids)
    {
        if (parent == null)
        {
            return;
        }

        hideChildren(parent.getChildren());
        hideChildren(parent.getDynamicChildren());

        unhideAndRevalidate(staticKids);
        unhideAndRevalidate(dynamicKids);

        parent.revalidate();
    }

    private void restoreBaseline()
    {
        for (Map.Entry<SnapTarget, ChildBackup> e : backups.entrySet())
        {
            Widget w = widget(e.getKey().packed);
            ChildBackup b = e.getValue();
            restoreChildren(w, b.stat, b.dyn);
        }
        backups.clear();
    }

    private static Widget[] merge(Widget[] a, Widget[] b)
    {
        if (a == null) return b;
        if (b == null) return a;
        final Widget[] out = new Widget[a.length + b.length];
        System.arraycopy(a, 0, out, 0, a.length);
        System.arraycopy(b, 0, out, a.length, b.length);
        return out;
    }

    /**
     * If the override is currently visible, rebuild it to reflect latest state.
     */
    public void refreshIfActive()
    {
        if (!overrideActive) return;
        clientThread.invokeLater(this::applyOverride);
    }

    /**
     * Entry point from the Music tab button; builds or refreshes the override UI.
     */
    public void overrideWithLatest()
    {
        if (unlocks.unlockedList().isEmpty())
        {
            return;
        }
        loadFavoritesIfNeeded();

        if (!overrideActive)
        {
            overrideActive = true;
            clientThread.invokeLater(() ->
            {
                applyOverride();
                spriteOverrideManager.register();
            });
        }
        else
        {
            clientThread.invokeLater(this::applyOverride);
        }
    }

    /**
     * Restore the stock Music tab.
     */
    public void restore()
    {
        if (!overrideActive)
        {
            return;
        }
        spriteOverrideManager.unregister();
        itemSpriteCache.clear();
        clientThread.invokeLater(this::revertOverride);
    }

    /**
     * Ensure stock top-row controls and the "View Unlocks" button are visible.
     */
    public void restoreTopRowControls()
    {
        forceShowCoreMusicControls();

        final Widget contents = widget(InterfaceID.Music.CONTENTS);
        if (contents != null)
        {
            final Widget btn = findByAction(contents, "View Unlocks");
            if (btn != null)
            {
                btn.setHidden(false);
                btn.revalidate();
            }
        }
    }

    private void loadFavoritesIfNeeded()
    {
        if (favoritesLoaded) return;
        favoritesLoaded = true;

        final String csv = configManager.getConfiguration(CFG_GROUP, CFG_FAVS);
        if (csv == null || csv.isEmpty()) return;

        for (String s : csv.split(","))
        {
            final String b = s.trim();
            if (!b.isEmpty()) favoriteBases.add(b);
        }
    }

    private void saveFavorites()
    {
        configManager.setConfiguration(CFG_GROUP, CFG_FAVS, String.join(",", favoriteBases));
    }

    private boolean isFavorite(String base)
    {
        return favoriteBases.contains(base);
    }

    private void toggleFavorite(String base)
    {
        if (!favoriteBases.remove(base)) favoriteBases.add(base);
        saveFavorites();
        applyOverride(); // re-sort and redraw grid
    }

    // helpers

    private void hideOtherMusicUi()
    {
        rememberAndHidePacked(InterfaceID.Music.JUKEBOX);
        rememberAndHideAll(RESTORE_FORCE_VISIBLE_PACKEDS);

        Widget np = widget(InterfaceID.Music.NOW_PLAYING);
        Widget c = widget(InterfaceID.Music.CONTROLS);

        if (np != null)
        {
            hideChildren(np.getChildren());
            hideChildren(np.getDynamicChildren());
            np.revalidate();
        }
        if (c != null)
        {
            hideChildren(c.getChildren());
            hideChildren(c.getDynamicChildren());
            c.revalidate();
        }
    }

    private Widget updateTitle()
    {
        Widget title = widget(InterfaceID.Music.NOW_PLAYING_TITLE);
        if (title != null)
        {
            if (originalTitleText == null)
            {
                originalTitleText = title.getText();
            }
            title.setText("Unlocked items");
            title.revalidate();
        }
        return title;
    }

    private int absX(Widget root, Widget w)
    {
        int x = 0;
        Widget cur = w;
        while (cur != null && root != null && cur.getId() != root.getId())
        {
            x += cur.getOriginalX();
            int pid = cur.getParentId();
            if (pid == -1)
            {
                break;
            }
            cur = client.getWidget(pid);
        }
        return x;
    }

    private int absY(Widget root, Widget w)
    {
        int y = 0;
        Widget cur = w;
        while (cur != null && root != null && cur.getId() != root.getId())
        {
            y += cur.getOriginalY();
            int pid = cur.getParentId();
            if (pid == -1)
            {
                break;
            }
            cur = client.getWidget(pid);
        }
        return y;
    }

    private int clamp(int v, int min, int max)
    {
        return Math.max(min, Math.min(max, v));
    }

    private void applyOverride()
    {
        ensureBaselineCaptured();
        iconBaseMap.clear();

        purgeOverrideWidgets();

        hideOtherMusicUi();

        final Widget root = widget(InterfaceID.Music.UNIVERSE);
        final Widget contents = widget(InterfaceID.Music.CONTENTS);
        final Widget frame = widget(InterfaceID.Music.FRAME);
        final Widget scrollable = widget(InterfaceID.Music.SCROLLABLE);
        final Widget jukebox = widget(InterfaceID.Music.JUKEBOX);
        final Widget scrollbar = widget(InterfaceID.Music.SCROLLBAR);

        if (contents != null)
        {
            pluginToggle = findByAction(contents, "View Unlocks");
            if (pluginToggle != null)
            {
                pluginToggle.setHidden(true);
                pluginToggle.revalidate();
            }
        }

        final Widget title = updateTitle();

        hideChildren(jukebox != null ? jukebox.getChildren() : null);
        hideChildren(jukebox != null ? jukebox.getDynamicChildren() : null);
        hideChildren(scrollable != null ? scrollable.getChildren() : null);
        hideChildren(scrollable != null ? scrollable.getDynamicChildren() : null);

        if (scrollable != null)
        {
            scrollable.deleteAllChildren();
            scrollable.revalidate();
        }

        final List<DisplayBase> bases = unlocks.unlockedList().stream()
                .map(b -> new DisplayBase(b, pickRepId(b)))
                .filter(db -> db.repId > 0)
                .collect(Collectors.toList());

        bases.sort(Comparator
                .comparing((DisplayBase db) -> !isFavorite(db.baseName))
                .thenComparing(db -> db.baseName.toLowerCase(Locale.ROOT)));

        setHiddenRevalidate(scrollable, false);
        setHiddenRevalidate(scrollbar, false);

        if (scrollable != null && scrollbar != null)
        {
            int displayIndex = 0;
            for (DisplayBase db : bases)
            {
                final Widget icon = scrollable.createChild(-1, WidgetType.GRAPHIC);
                createdScrollWidgets.add(icon);

                icon.setHidden(false);
                icon.setOriginalWidth(ICON_SIZE);
                icon.setOriginalHeight(ICON_SIZE);
                icon.setItemQuantityMode(ItemQuantityMode.NEVER);

                final int spriteId = itemSpriteCache.getSpriteId(db.repId);
                icon.setSpriteId(spriteId);

                final int col = displayIndex % COLUMNS;
                final int row = displayIndex / COLUMNS;
                final int x = MARGIN_X + col * (ICON_SIZE + PADDING);
                final int y = MARGIN_Y + row * (ICON_SIZE + PADDING);

                icon.setOriginalX(x);
                icon.setOriginalY(y);
                icon.revalidate();

                icon.setOnClickListener((JavaScriptCallback) (ScriptEvent ev) -> toggleFavorite(db.baseName));
                icon.setHasListener(true);

                if (isFavorite(db.baseName))
                {
                    final Widget star = scrollable.createChild(-1, WidgetType.GRAPHIC);
                    createdScrollWidgets.add(star);

                    star.setHidden(false);
                    star.setSpriteId(STAR_SPRITE);
                    star.setOriginalWidth(12);
                    star.setOriginalHeight(12);
                    star.setOriginalX(x + ICON_SIZE - 10);
                    star.setOriginalY(y - 2);
                    star.revalidate();
                }

                iconBaseMap.put(icon, db.baseName);
                displayIndex++;
            }

            final int rows = (bases.size() + COLUMNS - 1) / COLUMNS;
            scrollable.setScrollHeight(MARGIN_Y * 2 + rows * (ICON_SIZE + PADDING));
            scrollable.revalidate();
            revalidateScroll(scrollbar);
        }

        drawProgressStretchToFrame(root, title, frame,
                unlocks.unlockedList().size(),
                itemsRepo.getAllBases().size());

        if (root != null)
        {
            final Widget close = root.createChild(-1);
            close.setHidden(false);
            close.setType(WidgetType.GRAPHIC);
            close.setOriginalX(CLOSE_PAD);
            close.setOriginalY(CLOSE_PAD);
            close.setOriginalWidth(CLOSE_SIZE);
            close.setOriginalHeight(CLOSE_SIZE);
            close.setSpriteId(CLOSE_SPRITE);
            close.setAction(0, "Close");
            close.setOnOpListener((JavaScriptCallback) (ScriptEvent ev) -> restore());
            close.setHasListener(true);
            close.revalidate();
            createdRootWidgets.add(close);

            root.revalidate();
        }
    }

    private void drawProgressStretchToFrame(Widget root, Widget title, Widget frame, int unlocked, int total)
    {
        if (root == null || title == null)
        {
            return;
        }

        int fontId = title.getFontId();
        boolean shadowed = title.getTextShadowed();

        int titleX = absX(root, title);
        int titleY = absY(root, title);
        int titleW = title.getOriginalWidth();
        int titleH = title.getOriginalHeight();

        int frameX = frame != null ? absX(root, frame) : (titleX + titleW);
        int frameW = frame != null ? frame.getOriginalWidth() : 0;
        int frameRight = frameW > 0 ? (frameX + frameW) : (titleX + titleW);

        int barX = titleX;
        int barY = Math.max(0, titleY + titleH - 1);

        int newW = Math.max(120, frameRight - barX - 8);
        newW = clamp(newW, 0, 4096);

        final Widget bg = root.createChild(-1, WidgetType.RECTANGLE);
        createdRootWidgets.add(bg);
        bg.setHidden(false);
        bg.setFilled(true);
        bg.setTextColor(0x000000);
        bg.setOriginalX(barX);
        bg.setOriginalY(barY);
        bg.setOriginalWidth(newW);
        bg.setOriginalHeight(BAR_HEIGHT);
        bg.revalidate();

        final int border = 1;
        final int inner = Math.max(0, newW - border * 2);
        final int fillW = total == 0 ? 0 : Math.round(inner * (float) unlocked / (float) total);

        final Widget fill = root.createChild(-1, WidgetType.RECTANGLE);
        createdRootWidgets.add(fill);
        fill.setHidden(false);
        fill.setFilled(true);
        fill.setTextColor(0x00b33c);
        fill.setOriginalX(barX + border);
        fill.setOriginalY(barY + border);
        fill.setOriginalWidth(Math.max(0, fillW));
        fill.setOriginalHeight(BAR_HEIGHT - border * 2);
        fill.revalidate();

        final String txt = unlocked + "/" + total;
        final Widget label = root.createChild(-1, WidgetType.TEXT);
        createdRootWidgets.add(label);
        label.setHidden(false);
        label.setText(txt);
        label.setTextColor(0xFFFFFF);
        label.setFontId(fontId);
        label.setTextShadowed(shadowed);
        label.setOriginalX(barX + (newW / 2) - (txt.length() * 4));
        label.setOriginalY(barY + (BAR_HEIGHT / 2) - 6);
        label.setOriginalWidth(newW);
        label.setOriginalHeight(BAR_HEIGHT);
        label.revalidate();
    }

    private int pickRepId(String base)
    {
        try
        {
            final Set<Integer> ids = itemsRepo.getIdsForBase(base);
            if (ids == null || ids.isEmpty()) return 0;
            return ids.stream().min(Integer::compareTo).orElse(0);
        }
        catch (Exception e)
        {
            return 0;
        }
    }

    private void revertOverride()
    {
        if (!overrideActive) return;

        final Widget root = widget(InterfaceID.Music.UNIVERSE);
        final Widget scrollable = widget(InterfaceID.Music.SCROLLABLE);
        final Widget jukebox = widget(InterfaceID.Music.JUKEBOX);
        final Widget overlay = widget(InterfaceID.Music.OVERLAY);
        final Widget scrollbar = widget(InterfaceID.Music.SCROLLBAR);
        final Widget title = widget(InterfaceID.Music.NOW_PLAYING_TITLE);

        purgeOverrideWidgets();
        restoreBaseline();

        restoreHiddenStates();
        forceShowCoreMusicControls();

        if (scrollbar != null)
        {
            scrollbar.setHidden(false);
            scrollbar.revalidate();
            scrollbar.revalidateScroll();
        }
        if (overlay != null)
        {
            overlay.setHidden(false);
            overlay.revalidate();
        }

        if (title != null && originalTitleText != null)
        {
            title.setText(originalTitleText);
            title.revalidate();
        }

        runOnLoad(root);
        runOnLoad(overlay);
        runOnLoad(scrollbar);
        runOnLoad(jukebox);
        runOnLoad(scrollable);

        originalTitleText = null;
        iconBaseMap.clear();
        pluginToggle = null;

        overrideActive = false;
        restoreTopRowControls();
    }

    private void purgeOverrideWidgets()
    {
        purgeWidgets(createdRootWidgets);
        purgeWidgets(createdScrollWidgets);
        createdRootWidgets.clear();
        createdScrollWidgets.clear();
        iconBaseMap.clear();
    }

    /**
     * Forcefully removes widgets we created during override so they cannot
     * be resurrected by the music tab's onLoad() which tends to unhide children.
     */
    private static void purgeWidgets(List<Widget> widgets)
    {
        if (widgets == null)
        {
            return;
        }
        for (Widget w : widgets)
        {
            if (w == null)
            {
                continue;
            }
            try
            {
                w.setOnOpListener((JavaScriptCallback) null);
                w.setOnClickListener((JavaScriptCallback) null);
                w.setHasListener(false);
                w.setHidden(true);
                w.setOriginalX(0);
                w.setOriginalY(0);
                w.setOriginalWidth(0);
                w.setOriginalHeight(0);
                w.setType(0);
                w.revalidate();
            }
            catch (Exception ignored)
            {
            }
        }
    }

    private Widget findByAction(Widget parent, String action)
    {
        if (parent == null) return null;
        final Widget[] kids = merge(parent.getChildren(), parent.getDynamicChildren());
        if (kids == null) return null;
        for (Widget c : kids)
        {
            if (c == null) continue;
            final String[] actions = c.getActions();
            if (actions != null)
            {
                for (String a : actions)
                {
                    if (a != null && a.equalsIgnoreCase(action)) return c;
                }
            }
            final Widget deeper = findByAction(c, action);
            if (deeper != null) return deeper;
        }
        return null;
    }

    private void runOnLoad(Widget w)
    {
        if (w == null || w.getOnLoadListener() == null) return;
        w.revalidate();
    }

    private static final class DisplayBase
    {
        final String baseName;
        final int repId;

        DisplayBase(String baseName, int repId)
        {
            this.baseName = baseName;
            this.repId = repId;
        }
    }
}

